window.SDT_TERMS={"b":[{"ko":"파사드","en":"Facade","say":"건물에서 길을 향한 주된 겉면, 곧 건물의 얼굴","more":"양식의 특징이 가장 많이 드러나는 면이에요. 이 과목의 사진 문제는 거의 파사드를 보여 줘요."},{"ko":"입면","en":"Elevation","say":"건물 한 면을 정면으로 마주 보고 그린 그림","more":"개구부와 장식이 어떻게 줄 서 있는지가 보여요. 사진에 찍힌 얼굴이 대개 입면이에요."},{"ko":"개구부","en":"Opening","say":"벽에 뚫어 놓은 창과 문 자리","more":"크기와 모양과 배열이 양식을 가르는 첫 단서예요. 격자인지 아치인지 띠창인지를 봐요."},{"ko":"기단","en":"Base","say":"건물 맨 아래에서 몸통을 받쳐 주는 부분","more":"에펠탑은 기단, 몸통, 탑으로 구성되고, 설리번의 3단구성법에서도 저층부를 base 라고 불러요."},{"ko":"코니스","en":"Cornice","say":"건물 꼭대기에서 밖으로 내밀어 마감한 띠","more":"설리번의 웨인라이트 빌딩에는 우아한 코니스가 있고, 시카고 학파 고층 건물은 코니스를 기둥의 주두처럼 써요."},{"ko":"비례","en":"Proportion","say":"부분과 부분, 부분과 전체의 크기 관계","more":"절충주의는 전통적인 비례체계를 무시했고, 로스의 무장식은 비례를 더욱 돋보이게 한다고 평가돼요."},{"ko":"양식","en":"Style","say":"한 시기의 건물들이 함께 지키는 형태의 규칙과 그 이름","more":"시험은 사진을 주고 양식 이름을 묻고, 논술은 그 양식을 아는 대로 모두 쓰라고 해요."},{"ko":"평면","en":"Plan","say":"건물을 가로로 잘라 위에서 내려다본 그림","more":"방이 어떻게 놓이고 사람이 어디로 다니는지가 보여요. 사진만으로는 알 수 없는 정보예요."},{"ko":"단면","en":"Section","say":"건물을 세로로 잘라 옆에서 들여다본 그림","more":"층고와 높이 차이, 지붕의 모양이 보여요. 로스의 라움플란처럼 높이로 승부하는 집은 단면을 봐야 해요."},{"ko":"층고","en":"Floor Height","say":"한 층의 바닥에서 위층 바닥까지의 높이","more":"바그너는 각 층의 층고를 동일하게 평준화했고, 로스는 방마다 층고를 다르게 주는 라움플란을 썼어요."},{"ko":"중정","en":"Courtyard","say":"건물이 빙 둘러싼 가운데의 큰 마당"},{"ko":"라움플란","en":"Raumplan","say":"방마다 필요한 높이를 따로 주고 입체적으로 맞물리는 로스의 설계법","more":"'나는 평면, 입면, 단면이 아니라 공간을 설계한다'. 거실을 두 개 층으로 개방. 라움쿤스트와 구분."},{"ko":"기둥","en":"Column","say":"위에서 내려오는 무게를 받아 땅으로 보내는 수직 부재","more":"조적조에서는 벽이 이 일을 하고, 근대 건축에서는 기둥이 대신하면서 벽이 자유로워졌어요."},{"ko":"기둥과 보","en":"Post and Beam","say":"기둥을 세우고 그 위에 보를 걸어 무게를 받는 짜임","more":"벽이 무게를 받지 않아도 되므로 벽을 유리로 바꿀 수 있어요. 커튼월의 전제 조건이에요."},{"ko":"조적조","en":"Masonry","say":"벽돌이나 돌을 쌓아 벽 자체가 무게를 받는 구조","more":"높이 올릴수록 아래쪽 벽이 두꺼워져요. 모나드녹 빌딩은 1층 벽두께가 1.8m 예요."},{"ko":"압축","en":"Compression","say":"위에서 눌러 찌그러뜨리는 힘","more":"돌, 벽돌, 콘크리트, 주철은 압축에 강해요. 아치는 힘을 압축으로 바꿔 흘려보내는 장치예요."},{"ko":"스팬","en":"Span","say":"받침과 받침 사이, 기둥과 기둥 사이의 거리","more":"스팬이 길수록 기둥 없는 넓은 실내가 생겨요. 길게 벌린 것이 장스팬이에요."},{"ko":"커튼월","en":"curtain wall","say":"무게를 받지 않고 뼈대에 커튼처럼 걸어 놓은 바깥벽"},{"ko":"아치","en":"Arch","say":"개구부 위를 곡선으로 쌓아 무게를 양옆으로 흘려보내는 구조","more":"평평한 인방은 아래쪽이 당겨져서 길게 걸 수 없어요. 아치는 그 당김을 누름으로 바꿔 줘요."},{"ko":"볼트","en":"Vault","say":"아치를 한 방향으로 쭉 밀고 나간 터널 모양 천장","more":"정리노트와 강의는 배럴 보울트라고 적어요. 우편저축은행 주 업무실 지붕이 그 예예요."},{"ko":"돔 지붕","en":"Dome","say":"아치를 한 점 둘레로 빙 돌려 만든 반구 모양 지붕","more":"쁘렝땅 백화점의 천장 유리 돔, 분리파 전시관의 금색 월계수 잎 돔이 이 과목의 예예요."},{"ko":"인장","en":"Tension","say":"양쪽에서 잡아당겨 늘이는 힘","more":"돌과 벽돌과 콘크리트는 인장에 약해요. 철골과 철근이 이 약점을 메워 주었어요."},{"ko":"트러스","en":"Truss","say":"삼각형을 이어 붙여 긴 거리를 가볍게 건너는 뼈대","more":"삼각형은 모양이 안 변해서 가벼운 재료로도 넓은 지붕을 덮을 수 있어요. AEG 터빈공장 내부가 아치형 트러스예요."},{"ko":"주철","en":"cast iron","say":"탄소가 많아 압축에 강하지만 부러지기 쉬운 철","more":"주철, 단철, 강철 구분: 주철은 잘 부러짐, 단철은 잘 늘어남, 강철은 다 강함."},{"ko":"단철","en":"wrought iron","say":"탄소가 적어 잘 늘어나는 철"},{"ko":"철골(강철)","en":"steel","say":"인장과 압축에 모두 강한 근대 재료","more":"1709년 발명되어 공업 재료로 쓰이다 1820년경 건축에 도입, 1870년을 기점으로 사용량이 크게 늘어남."},{"ko":"판유리","en":"Plate Glass","say":"크고 평평하게 만든 유리판","more":"값싼 유리가 보급되면서 넓은 창문이 가능해졌고, 나중에는 벽 전체가 유리가 되었어요."},{"ko":"장스팬","en":"","say":"기둥과 기둥 사이를 길게 벌린 구조","more":"철 건축의 장점 세트: 장스팬, 가는 기둥, 밝은 실내."},{"ko":"철근콘크리트","en":"Reinforced Concrete","say":"콘크리트 안에 철근을 넣어 누름과 당김을 함께 버티게 한 재료","more":"콘크리트는 압축에 강하고 인장에 약해서, 당겨지는 자리에 철근을 넣어요. 철물과 함께 19세기의 두 신재료예요."},{"ko":"캔틸레버","en":"cantilever","say":"한쪽 끝만 고정하고 다른 끝은 받침 없이 내민 구조"},{"ko":"필로티","en":"Pilotis","say":"건물을 기둥으로 들어 올려 아래를 비우는 방식","more":"르 코르뷔지에가 바이센호프에서 개방적인 평면 개념과 함께 제시."},{"ko":"평지붕","en":"Flat Roof","say":"바이센호프 주택들이 공통으로 쓴 평평한 지붕"},{"ko":"조소성","en":"","say":"굳기 전 찰흙처럼 모양을 빚을 수 있는 콘크리트의 성질"},{"ko":"절충주의","en":"","say":"용도와 상관없이 여러 역사 양식을 골라 외관을 꾸민 경향","more":"부정적으로 평가하는 쪽에서는 역사주의(Historism)라고도 함. 19세기 후반의 양식적 혼란기."},{"ko":"역사주의","en":"Historism","say":"과거 고전 형상에서 영감을 얻어 양식을 되풀이하는 태도","more":"바그너는 합리적 도시 문명을 위해 역사주의를 격퇴해야 한다고 주장. 강의자료 표기는 Historism. 통상 영어 표기는 Historicism."},{"ko":"미술공예운동","en":"Arts and Crafts Movement","say":"기계 생산에 반발해 수공예의 즐거움과 정직함을 되찾자는 운동","more":"1860-1900. 1888년 런던 전시회에서 Arts and Crafts Exhibition Society 이름 처음 사용. 비싸서 대중 수요를 못 채운 한계, 아르누보에 영향."},{"ko":"아르 누보","en":"Art Nouveau","say":"과거 양식 대신 자연의 곡선으로 새 양식을 만든 예술 사조","more":"프랑스어로 새로운 미술. 1890-1910, 최고조 1890-1905. '예술에는 일정한 형식이 없다'. 비대칭, 철과 유리, 공간보다 표면과 장식."},{"ko":"매스","en":"Mass","say":"건물이 이루는 큰 덩어리","more":"모나드녹 빌딩은 매스와 비례로 현대 문명의 힘을 전해야 한다고 했고, 그로피우스는 형태와 매스에 집중했어요."},{"ko":"캡션","en":"Caption","say":"그림 밑에 붙는 건축가, 작품 이름, 도시, 연도 넉 줄","more":"이 과목의 시험은 이 넉 줄의 짝을 계속 물어요. 괄호 안의 촬영이나 복원 연도는 완성 연도가 아니에요."},{"ko":"처마","en":"Eaves","say":"지붕이 벽 밖으로 내밀어 나온 부분","more":"처마가 깊으면 전통적인 집, 처마가 없으면 근대적인 집으로 읽히는 경우가 많아요."},{"ko":"박공","en":"Gable","say":"경사지붕의 끝에 생기는 삼각형 벽면","more":"절충주의 주택이 상투적인 수법으로 박공과 지붕창을 썼다고 강의가 지적해요."},{"ko":"지붕창","en":"Dormer","say":"경사지붕을 뚫고 올라온 작은 창","more":"박공과 함께 절충주의 주택의 상투적인 수법으로 꼽혀요."},{"ko":"내력벽","en":"Load-bearing Wall","say":"위층의 무게를 직접 받아 내리는 벽","more":"내력벽은 함부로 뚫을 수 없어요. 그래서 조적조 건물의 창은 작고 띄엄띄엄해요."}],"1":[{"ko":"계몽주의","en":"","say":"시민의식이 깨어나 교회와 국가의 절대주의가 쇠퇴한 17~18세기 사상","more":"민주주의, 자유, 평등을 중시. 미국 독립(1776), 프랑스 혁명(1789)으로 이어지고 시민계층이 사회의 새 주체가 됨."},{"ko":"산업혁명","en":"","say":"18세기 말 영국에서 기계와 공업 중심으로 사회가 바뀐 대변혁","more":"건축에는 유리, 콘크리트의 대량생산, 도시화와 집합주택, 관청, 은행, 사무소 같은 새 건축 과제를 낳음."},{"ko":"농업혁명","en":"","say":"산업혁명 이전에 농업기술 발달로 잉여생산물을 늘린 변화","more":"농장이 대규모화되고, 모직물 공업과 양 사육이 늘며 노동자가 도시로 유입됨."},{"ko":"주철","en":"cast iron","say":"탄소가 많아 압축에 강하지만 부러지기 쉬운 철","more":"주철, 단철, 강철 구분: 주철은 잘 부러짐, 단철은 잘 늘어남, 강철은 다 강함."},{"ko":"단철","en":"wrought iron","say":"탄소가 적어 잘 늘어나는 철"},{"ko":"철골(강철)","en":"steel","say":"인장과 압축에 모두 강한 근대 재료","more":"1709년 발명되어 공업 재료로 쓰이다 1820년경 건축에 도입, 1870년을 기점으로 사용량이 크게 늘어남."},{"ko":"장스팬","en":"","say":"기둥과 기둥 사이를 길게 벌린 구조","more":"철 건축의 장점 세트: 장스팬, 가는 기둥, 밝은 실내."},{"ko":"갤러리 형","en":"","say":"중앙의 큰 로비를 전시공간이 에워싸는 박물관 형식","more":"중앙로비 채광을 위해 천장을 철물과 유리로 덮음. 대형 전시공간의 표준형."},{"ko":"만국박람회","en":"","say":"새 공산품을 전시하며 국가 간 산업화를 겨룬 행사","more":"대부분 일회용 건물이라 건축 실험의 부담이 적었음. 1851 런던, 1855와 1867 파리, 1889 파리."},{"ko":"대박람회","en":"","say":"영국이 대성공으로 이끈 1851년 런던 만국박람회의 별칭"},{"ko":"수정궁","en":"Crystal Palace","say":"1851년 런던 만국박람회를 위해 건물 전체를 유리로 지은 전시관","more":"조셉 팩스턴 설계. 우아하고 경제적이며 구조는 단순하고 정적."},{"ko":"조셉 팩스턴","en":"","say":"수정궁을 설계한 인물"},{"ko":"에펠탑","en":"","say":"1889년 파리박람회에 구스타브 에펠이 세운 310m 탑","more":"다리에서 쌓은 아치 기술을 수직으로 올림. 혁명 100주년 박람회에서 수정궁을 능가."},{"ko":"기계관","en":"","say":"1889년 파리박람회에서 힌지 이음새로 확장 가능하게 지은 전시관","more":"수정궁보다 구조적으로 훨씬 강하고 큼."},{"ko":"프리패브","en":"","say":"규격화된 부재를 현장에서 조립하는 공법","more":"만국박람회 건축의 빠른 조립, 해체 요구가 그 출발점."},{"ko":"그랑 팔레","en":"","say":"1900년 파리 만국박람회장으로 지은 철과 유리 전시공간"},{"ko":"갤러리 라파예트 백화점","en":"","say":"유리와 철물 골격으로 천장을 덮은 파리 백화점의 대표 아이콘"},{"ko":"쁘렝땅 백화점","en":"","say":"천장 유리 돔을 스테인드글라스로 장식한 파리 백화점"},{"ko":"팜 하우스","en":"","say":"런던 큐가든에 있는 철과 유리의 온실","more":"빈에 있는 것은 팔멘하우스. 헷갈리지 않게."},{"ko":"전원도시","en":"Garden City","say":"도시와 전원의 성격을 함께 지닌 저밀도 자족도시 구상","more":"하워드 제안. 인구 5만 8천 명 중심도시를 32,000명 도시 6개가 원형으로 둘러싸고 철도로 연결. 외곽 농지로 확장 제한."},{"ko":"에베네저 하워드","en":"","say":"전원도시 이론을 제시한 인물(1850-1928)","more":"실제 레치워스 설계는 하워드가 아니라 언윈과 파커."},{"ko":"내일","en":"Tomorrow","say":"최적인구 32,000명을 제시한 하워드의 1898년 저서"},{"ko":"미술공예운동","en":"Arts and Crafts Movement","say":"기계 생산에 반발해 수공예의 즐거움과 정직함을 되찾자는 운동","more":"1860-1900. 1888년 런던 전시회에서 Arts and Crafts Exhibition Society 이름 처음 사용. 비싸서 대중 수요를 못 채운 한계, 아르누보에 영향."},{"ko":"레치워스","en":"Letchworth","say":"1905년 영국 헤트포드셔에 세운 최초의 전원도시","more":"정원 딸린 독립주택, 공원, 엄격한 보차분리."},{"ko":"언윈과 파커","en":"","say":"레치워스를 설계한 레이먼드 언윈과 베리 파커"},{"ko":"보차분리","en":"","say":"보행자 동선과 차량 동선을 분리하는 계획 기법"},{"ko":"존 러스킨","en":"","say":"기계 생산을 비판하고 중세 수공예로 돌아가자고 한 영국 평론가","more":"1819-1900. 기능, 재료, 생산 기술을 표현하는 정직성을 중시. 1871년 길드 결성."},{"ko":"어거스트 퓨진","en":"","say":"러스킨과 함께 기독교 사회주의 건축 운동을 이끈 인물","more":"1812-1852."},{"ko":"고딕 리바이벌","en":"","say":"중세 고딕 양식과 수공예로 돌아가자는 복고 흐름","more":"영국은 고딕 종주국이라는 자부심으로 가장 늦게까지 고딕을 지속. 프랑스는 고딕의 구조 합리주의를 철물 건축에 적용."},{"ko":"빅토리안 고딕","en":"","say":"영국의 고딕 리바이벌에 붙은 별칭"},{"ko":"기독교 사회주의","en":"","say":"중세 가톨릭 부활에 사회주의를 결합한 건축 운동","more":"자본주의 폐해에 대한 대안 운동으로 등장."},{"ko":"길드","en":"","say":"재료의 정직성과 수공예를 강조하며 1871년 결성된 단체"},{"ko":"윌리엄 모리스","en":"William Morris","say":"미술공예운동을 이끈 벽지, 직물 중심의 디자이너","more":"1834-1896. 식물, 꽃, 새 같은 자연 모티프."},{"ko":"모리스 마샬 포크너","en":"","say":"1861년 모리스가 세워 벽지, 직물, 가구, 스테인드글라스를 만든 회사"},{"ko":"붉은 집","en":"Red House","say":"필립 웹과 모리스가 1859년 설계한 현대 주택의 효시","more":"불규칙한 평면(기능에 따른 자유로운 구성), 내부와 외부 일체화, 성실한 재료, 소극적인 외관."},{"ko":"필립 웹","en":"","say":"모리스와 함께 붉은 집을 설계한 건축가"},{"ko":"현대주택의 계획 원리","en":"","say":"건축가 스티븐슨이 제시한 근대 주택 평면 원리","more":"공간의 명확한 기능 구분, 계단실과 통로 면적 최소화, 부엌과 식당 동선 최소화."},{"ko":"C. F. A. 보이지","en":"","say":"단순한 실내로 모더니즘을 예고한 영국 주택 건축가","more":"1857-1941. 작품 브로들리(1898), 오챠드(1900), 과수원 주택(1899), Homestead(1906)."},{"ko":"브로들리","en":"Broadleys","say":"호수 쪽으로 휘어진 창 3개를 낸 보이지의 전원 주택(1898)"},{"ko":"오챠드","en":"","say":"모더니즘을 암시하는 단순한 거실을 둔 보이지의 자택(1900)"},{"ko":"찰스 레니 매킨토시","en":"","say":"곡선에서 기하학적이고 간결한 양식으로 옮겨 간 스코틀랜드 건축가","more":"1868-1928. 수채화 화가이기도 함. 호프만의 사각형에 영향."},{"ko":"힐하우스","en":"","say":"회벽, 급경사 슬레이트 지붕, 반원형 탑을 지닌 매킨토시 주택(1904)","more":"평면 주요부와 서비스 윙이 직각 배치, 그리드로 분할된 개구부."},{"ko":"계몽주의","en":"Enlightenment","say":"시민의식이 깨어나 교회와 국가의 절대주의가 쇠퇴한 17~18세기 사상","more":"민주주의, 자유, 평등을 중시. 미국 독립(1776), 프랑스 혁명(1789)으로 이어지고 시민계층이 사회의 새 주체가 됨."},{"ko":"산업혁명","en":"Industrial Revolution","say":"18세기 말 영국에서 기계와 공업 중심으로 사회가 바뀐 대변혁","more":"건축에는 유리, 콘크리트의 대량생산, 도시화와 집합주택, 관청, 은행, 사무소 같은 새 건축 과제를 낳음."},{"ko":"농업혁명","en":"Agricultural Revolution","say":"산업혁명 이전에 농업기술 발달로 잉여생산물을 늘린 변화","more":"농장이 대규모화되고, 모직물 공업과 양 사육이 늘며 노동자가 도시로 유입됨."},{"ko":"에펠탑","en":"Eiffel Tower","say":"1889년 파리박람회에 구스타브 에펠이 세운 310m 탑","more":"다리에서 쌓은 아치 기술을 수직으로 올림. 혁명 100주년 박람회에서 수정궁을 능가."},{"ko":"만국박람회","en":"World Exposition","say":"새 공산품을 전시하며 국가 간 산업화를 겨룬 행사","more":"대부분 일회용 건물이라 건축 실험의 부담이 적었음. 1851 런던, 1855와 1867 파리, 1889 파리."},{"ko":"대박람회","en":"Great Exhibition","say":"영국이 대성공으로 이끈 1851년 런던 만국박람회의 별칭"},{"ko":"조셉 팩스턴","en":"Joseph Paxton","say":"수정궁을 설계한 인물"},{"ko":"기계관","en":"Machinery Hall","say":"1889년 파리박람회에서 힌지 이음새로 확장 가능하게 지은 전시관","more":"수정궁보다 구조적으로 훨씬 강하고 큼."},{"ko":"프리패브","en":"Prefabrication","say":"규격화된 부재를 현장에서 조립하는 공법","more":"만국박람회 건축의 빠른 조립, 해체 요구가 그 출발점."},{"ko":"에베네저 하워드","en":"Ebenezer Howard","say":"전원도시 이론을 제시한 인물(1850-1928)","more":"실제 레치워스 설계는 하워드가 아니라 언윈과 파커."},{"ko":"언윈과 파커","en":"Unwin and Parker","say":"레치워스를 설계한 레이먼드 언윈과 베리 파커"},{"ko":"존 러스킨","en":"John Ruskin","say":"기계 생산을 비판하고 중세 수공예로 돌아가자고 한 영국 평론가","more":"1819-1900. 기능, 재료, 생산 기술을 표현하는 정직성을 중시. 1871년 길드 결성."},{"ko":"어거스트 퓨진","en":"Augustus Pugin","say":"러스킨과 함께 기독교 사회주의 건축 운동을 이끈 인물","more":"1812-1852."},{"ko":"고딕 리바이벌","en":"Gothic Revival","say":"중세 고딕 양식과 수공예로 돌아가자는 복고 흐름","more":"영국은 고딕 종주국이라는 자부심으로 가장 늦게까지 고딕을 지속. 프랑스는 고딕의 구조 합리주의를 철물 건축에 적용."},{"ko":"빅토리안 고딕","en":"Victorian Gothic","say":"영국의 고딕 리바이벌에 붙은 별칭"},{"ko":"기독교 사회주의","en":"Christian Socialism","say":"중세 가톨릭 부활에 사회주의를 결합한 건축 운동","more":"자본주의 폐해에 대한 대안 운동으로 등장."},{"ko":"길드","en":"Guild","say":"재료의 정직성과 수공예를 강조하며 1871년 결성된 단체"},{"ko":"모리스 마샬 포크너","en":"Morris, Marshall, Faulkner and Co.","say":"1861년 모리스가 세워 벽지, 직물, 가구, 스테인드글라스를 만든 회사"},{"ko":"필립 웹","en":"Phillip Webb","say":"모리스와 함께 붉은 집을 설계한 건축가","more":"강의자료 표기는 Phillip Webb. 통상 표기는 l 하나인 Philip Webb."},{"ko":"C. F. A. 보이지","en":"C. F. A. Voysey","say":"단순한 실내로 모더니즘을 예고한 영국 주택 건축가","more":"1857-1941. 작품 브로들리(1898), 오챠드(1900), 과수원 주택(1899), Homestead(1906)."},{"ko":"오챠드","en":"The Orchard","say":"모더니즘을 암시하는 단순한 거실을 둔 보이지의 자택(1900)"},{"ko":"그랑 팔레","en":"Grand Palais","say":"1900년 파리 만국박람회장으로 지은 철과 유리 전시공간"},{"ko":"갤러리 라파예트 백화점","en":"Galeries Lafayette","say":"유리와 철물 골격으로 천장을 덮은 파리 백화점의 대표 아이콘"},{"ko":"쁘렝땅 백화점","en":"Printemps","say":"천장 유리 돔을 스테인드글라스로 장식한 파리 백화점"},{"ko":"팜 하우스","en":"Palm House","say":"런던 큐가든에 있는 철과 유리의 온실","more":"빈에 있는 것은 팔멘하우스. 헷갈리지 않게."}],"2":[{"ko":"절충주의","en":"","say":"용도와 상관없이 여러 역사 양식을 골라 외관을 꾸민 경향","more":"부정적으로 평가하는 쪽에서는 역사주의(Historism)라고도 함. 19세기 후반의 양식적 혼란기."},{"ko":"역사주의","en":"","say":"과거 고전 형상에서 영감을 얻어 양식을 되풀이하는 태도","more":"바그너는 합리적 도시 문명을 위해 역사주의를 격퇴해야 한다고 주장."},{"ko":"아르 누보","en":"Art Nouveau","say":"과거 양식 대신 자연의 곡선으로 새 양식을 만든 예술 사조","more":"프랑스어로 새로운 미술. 1890-1910, 최고조 1890-1905. '예술에는 일정한 형식이 없다'. 비대칭, 철과 유리, 공간보다 표면과 장식."},{"ko":"유겐트슈틸","en":"Jugendstil","say":"아르누보를 독일어로 옮긴, 곡선을 기하학적으로 정리한 독일 양식","more":"1896년 같은 이름(young style)의 잡지 발간과 함께 시작. 첫 사례는 베렌스의 1898년 그래픽."},{"ko":"아르데코","en":"","say":"1925년 파리 박람회에서 이름을 딴 번개, 지그재그 기하 장식 양식","more":"바우하우스보다 부드럽고 대중적. 매끄러운 표면, 이국적 표현, 값비싼 재료, 마천루 형태를 빌림."},{"ko":"빈 분리파","en":"Wiener Secession","say":"1897년 클림트가 기성 예술에 반기를 들며 결성한 조직","more":"제체시온. 미술과 생활의 새 관계 모색, 예술가 개인 존중, 장르 구분 폐지."},{"ko":"미술공예운동","en":"Arts and Crafts Movement","say":"기계 생산에 반발해 수공예의 즐거움과 정직함을 되찾자는 운동","more":"1860-1900. 1888년 런던 전시회에서 Arts and Crafts Exhibition Society 이름 처음 사용. 비싸서 대중 수요를 못 채운 한계, 아르누보에 영향."},{"ko":"붉은 집","en":"Red House","say":"필립 웹과 모리스가 1859년 설계한 현대 주택의 효시","more":"불규칙한 평면(기능에 따른 자유로운 구성), 내부와 외부 일체화, 성실한 재료, 소극적인 외관."},{"ko":"구스타프 클림트","en":"","say":"빈 분리파를 이끈 화가, 베토벤 프리즈와 스토클레 모자이크를 제작"},{"ko":"오토 바그너","en":"Otto Wagner","say":"'필요만이 예술의 주인'이라 한 빈의 합리적 기능주의 건축가","more":"1841-1918. '실용적이지 않은 것은 아름다울 수 없다'. 작품 순서 앙커하우스(1895), 마욜리카하우스(1898), 칼스플라츠 역사(1901), 우편저축은행(1906), 노이슈티프트가세(1911)."},{"ko":"단철","en":"wrought iron","say":"탄소가 적어 잘 늘어나는 철"},{"ko":"빅토르 오르타","en":"Victor Horta","say":"흐르는 곡선과 가는 금속 기둥을 쓴 벨기에 아르누보 건축가","more":"1861-1947. 매다는 전기 조명의 가능성을 개척."},{"ko":"오르타 저택","en":"","say":"타일, 캐비닛, 조명, 가구까지 오르타가 직접 디자인한 자택(1911)","more":"지금의 오르타 박물관. 남의 집(타셀)이 먼저, 내 집(오르타)이 나중."},{"ko":"타셀 저택","en":"","say":"평면 일부를 파내 좁은 공간의 채광을 해결한 오르타의 주택(1893)","more":"1층 평면에 융통성, 밝고 가벼운 공간."},{"ko":"엑토르 기마르","en":"Hector Guimard","say":"아르누보를 파리 지하철 입구에 도입한 프랑스 건축가","more":"1867-1942. 표준화된 금속 요소를 조립해 다양한 크기의 입구 키오스크를 만듦."},{"ko":"카스텔 베랑제","en":"","say":"기마르가 설계한 파리 공동주택(1898)"},{"ko":"찰스 레니 매킨토시","en":"","say":"곡선에서 기하학적이고 간결한 양식으로 옮겨 간 스코틀랜드 건축가","more":"1868-1928. 수채화 화가이기도 함. 호프만의 사각형에 영향."},{"ko":"힐하우스","en":"","say":"회벽, 급경사 슬레이트 지붕, 반원형 탑을 지닌 매킨토시 주택(1904)","more":"평면 주요부와 서비스 윙이 직각 배치, 그리드로 분할된 개구부."},{"ko":"알폰스 무하","en":"","say":"꽃과 덩굴에 둘러싸인 여인을 그린 아르 누보 포스터 화가","more":"클림트와 함께 강의가 든 아르 누보 회화의 대표 화가예요."},{"ko":"호프 파빌리온","en":"","say":"오토 바그너가 1898년 오스트리아 빈에 지은 건물","more":"둥근 지붕과 곡선 난간, 식물 무늬 금속 장식이 아르 누보 특징을 보여 줘요."},{"ko":"포르트 도핀 역 입구","en":"","say":"기마르가 파리에 만든 아르 누보 지하철 입구","more":"부채꼴 유리 차양과 METROPOLITAIN 간판이 달린 키오스크예요."},{"ko":"바스티유 역 출입문","en":"","say":"기마르가 만든 파리 바스티유 지하철역 출입문(c. 1900)","more":"물결치는 금속 차양과 곡선 뼈대로 된 입구 그림으로 슬라이드에 실려 있어요."},{"ko":"House for an Art Lover","en":"","say":"독일 디자인 잡지 공모전에 낸 매킨토시의 주택안(1901)"},{"ko":"글래스고 예술학교","en":"","say":"아르데코를 예견한, 아르누보와 모던의 경계에 선 매킨토시 작품(1899)","more":"1909년 도서관 커튼월 증축."},{"ko":"고딕 리바이벌","en":"","say":"중세 고딕 양식과 수공예로 돌아가자는 복고 흐름","more":"영국은 고딕 종주국이라는 자부심으로 가장 늦게까지 고딕을 지속. 프랑스는 고딕의 구조 합리주의를 철물 건축에 적용."},{"ko":"안토니 가우디","en":"","say":"3차원 곡선과 특이한 장식을 쓴 바르셀로나 건축가","more":"1852-1926. 중세건축의 영향, 벽돌과 석재, 표현주의적, 초현실주의의 선조."},{"ko":"사그라다 파밀리아","en":"","say":"고딕과 아르누보를 결합해 1882년부터 짓고 있는 가우디 작품"},{"ko":"카사 바트요","en":"","say":"중앙 코트와 구부러진 벽으로 방을 만든 가우디 작품(1906)"},{"ko":"카사 엘 카프리초","en":"","say":"벽돌과 해바라기 타일로 띠를 두른 가우디의 초기 주택(1885)","more":"스페인 꼬미야스에 있어요. 슬라이드 캡션에 안토니 가우디, 1885 로 적혀 있어요."},{"ko":"구엘 공원","en":"","say":"깨진 타일을 붙여 꾸민 가우디의 바르셀로나 공원(1914)","more":"물결치는 벤치, 기둥이 늘어선 홀, 타일 도마뱀 분수가 슬라이드에 나와요."},{"ko":"벽면 부조 디자인","en":"","say":"매킨토시가 1906년에 만든 벽 장식 부조","more":"장미 모양 덩어리와 가는 선이 벽 한 면을 덮는 작품이에요."},{"ko":"마틸덴회헤","en":"","say":"유겐트슈틸의 무대가 된 독일 다름슈타트의 장소(1901)"},{"ko":"요제프 마리아 올브리히","en":"","say":"분리파 전시관과 다름슈타트 예술가회관을 지은 건축가","more":"빈과 다름슈타트를 오감. 작품 순서: 분리파 전시관(1898), 예술가회관(1901), 결혼기념탑(1905), 글뤼커트 주택(1911)."},{"ko":"그로세스 글뤼커트 주택","en":"","say":"외부 곡선과 내부 직선을 결합하고 오메가 형태를 쓴 올브리히 주택(1911)","more":"곡선도 타원을 잘라낸 기하학적 곡선이라 아르누보의 자유 곡선과 다름."},{"ko":"오메가 형태","en":"","say":"기하학 도형에서 도출한 올브리히만의 조형 어휘"},{"ko":"장식물","en":"ornament","say":"벽 자체가 조각처럼 기능하는 바로크식 입체 장식","more":"올브리히와 바그너는 ornament가 아니라 decoration을 택함."},{"ko":"치장","en":"decoration","say":"밋밋한 벽에 2차원 마감재를 덧입히는 면 처리"},{"ko":"총체예술","en":"Total Art","say":"건물부터 가구, 문손잡이까지 하나의 통일된 앙상블로 만드는 개념","more":"건축과 통합된 인테리어 개념 등장, 가구 제작자가 예술가 지위를 얻음. 목표는 라움쿤스트."},{"ko":"라움쿤스트","en":"Raumkunst","say":"공간 자체가 예술이 되는 수준, 총체예술의 목표","more":"Space Art. 로스의 라움플란(공간 설계법)과 헷갈리지 않게."},{"ko":"라움플란","en":"Raumplan","say":"방마다 필요한 높이를 따로 주고 입체적으로 맞물리는 로스의 설계법","more":"'나는 평면, 입면, 단면이 아니라 공간을 설계한다'. 거실을 두 개 층으로 개방. 라움쿤스트와 구분."},{"ko":"베렌스 주택","en":"","say":"현관, 뮤직룸, 식당과 식기까지 통합 디자인한 다름슈타트 주택(1911)","more":"페터 베렌스 설계."},{"ko":"페터 베렌스","en":"","say":"AEG 터빈공장과 베렌스 주택을 설계한 독일 건축가","more":"1868-1940. 1898년 유겐트슈틸 그래픽도 디자인."},{"ko":"윌리엄 모리스","en":"William Morris","say":"미술공예운동을 이끈 벽지, 직물 중심의 디자이너","more":"1834-1896. 식물, 꽃, 새 같은 자연 모티프."},{"ko":"카사 밀라","en":"","say":"물결치는 돌 외벽과 철제 발코니를 가진 가우디의 공동주택(1912)","more":"스페인 바르셀로나. 평면에 둥근 중정이 두 개 뚫려 있어요."},{"ko":"예술가회관","en":"","say":"올브리히가 다름슈타트에 지은 예술가 마을의 중심 건물(1901)","more":"에른스트 루드비히하우스라고도 해요. 큰 아치 현관 양옆에 거인 조각이 서 있어요."},{"ko":"결혼기념탑","en":"","say":"꼭대기가 손가락 다섯처럼 둥글게 솟은 올브리히의 벽돌 탑(1905)","more":"독일 다름슈타트에 있어요. 마틸덴회헤에서 가장 눈에 띄는 건물이에요."},{"ko":"뉴 빅토리아 시네마","en":"","say":"Trent and Lewis 가 1929년 영국 런던에 지은 아르데코 극장","more":"천장에 별 모양으로 뻗은 조명이 달려 있어요."},{"ko":"크라이슬러 빌딩","en":"","say":"스테인레스 첨탑까지 계단식으로 쌓은 아르데코 마천루(1930)","more":"윌리엄 밴 앨런, 뉴욕."},{"ko":"데일리 익스프레스 빌딩","en":"","say":"테라조 계단과 별 폭발 모양 은색 천장을 둔 런던 아르데코 건물(1931)","more":"파도형 탄성고무 바닥, 블랙 대리석 벽, 대영제국 수호 뮤즈 장식."},{"ko":"시카고 학파","en":"","say":"1871년 대화재 뒤 철골과 엘리베이터로 고층 사무소를 지은 흐름","more":"철골에 테라코타 외벽, 베이스, 바디, 코니스의 3부분 분할, 시카고 창."},{"ko":"시카고 대화재","en":"","say":"1871년 시카고 상업지구 전체와 주거지 3분의 1을 태운 화재"},{"ko":"시카고 창","en":"","say":"3개로 나뉘고 격자이며 돌출된 창"},{"ko":"주철","en":"cast iron","say":"탄소가 많아 압축에 강하지만 부러지기 쉬운 철","more":"주철, 단철, 강철 구분: 주철은 잘 부러짐, 단철은 잘 늘어남, 강철은 다 강함."},{"ko":"철골(강철)","en":"steel","say":"인장과 압축에 모두 강한 근대 재료","more":"1709년 발명되어 공업 재료로 쓰이다 1820년경 건축에 도입, 1870년을 기점으로 사용량이 크게 늘어남."},{"ko":"커튼월","en":"curtain wall","say":"무게를 받지 않고 뼈대에 커튼처럼 걸어 놓은 바깥벽"},{"ko":"홈 인슈어런스 빌딩","en":"","say":"철골조와 커튼월로 지은 대표적 초기 철골조 건물(1885)","more":"윌리엄 제니. 1931년 철거."},{"ko":"오디토리엄 빌딩","en":"","say":"오피스, 호텔, 오페라 극장을 합친 복합건물(1889)","more":"아들러 앤드 설리번. 음향설계와 냉방장치."},{"ko":"모나드녹 빌딩","en":"","say":"1층 벽두께 1.8m 조적조에 장식을 뺀 존 루트의 건물(1893)","more":"'장식을 다용하는 것은 불필요하며 악덕이다'."},{"ko":"리라이언스 빌딩","en":"","say":"외관에 강철 골조를 드러낸 번햄의 16층 건물(1895)","more":"시카고파 정신의 상징."},{"ko":"루이스 설리번","en":"Louis Sullivan","say":"장식이 기능과 생명을 표현한다고 본 시카고 학파의 대표 건축가","more":"1856-1924. 저서 '예술적인 고층 사무소 건축'. 작품 순서 웨인라이트(1891), 개런티(1895), 카슨 피리 스콧(1896)."},{"ko":"웨인라이트 빌딩","en":"","say":"세로줄로 수직성을 강조한 설리번 1단계 11층 철골 건물(1891)","more":"세인트루이스. 격자 파사드, 프리캐스트 테라코타 장식."},{"ko":"개런티 트러스트 빌딩","en":"","say":"이슬람풍 장식을 전 표면에 쓴 설리번 2단계 건물(1895)","more":"버팔로. 아치를 애틱 하부까지 밀어올려 수직성 강조."},{"ko":"3단구성법","en":"","say":"저층부 base, 중간층 shaft, 지붕층 attic으로 나누는 설리번의 구성","more":"시카고 학파 일반론(베이스, 바디, 코니스)과 구분."},{"ko":"카슨 피리 스콧 백화점","en":"Carson Pirie Scott","say":"2층 높이 주철 파사드에 장식이 줄어든 설리번 3단계 작품(1896)","more":"코너의 원주형 기둥이 모서리의 장소성을 강조."},{"ko":"트리뷴 타워","en":"","say":"시카고 트리뷴 사옥 공모전 당선작으로 1925년 완공된 건물","more":"후드와 하우얼스 안. 로스는 1922년 거대한 도리아식 기둥 형태를 제출."},{"ko":"아돌프 로스","en":"Adolf Loos","say":"장식을 타락이라 비난하고 라움플란을 쓴 빈 건축가","more":"1870-1933. 제체시온의 심미적 경향을 비판. 작품 순서 카페 무제움, 아메리칸 바(1908), 슈타이너(1910), 로스하우스(1912), 슈트라서(1918), 뮐러(1930)."},{"ko":"시카고 워터타워","en":"","say":"1869년에 지어져 시카고 대화재에서 살아남은 돌 탑","more":"Chicago Water Tower and Pumping Station. 성처럼 생긴 급수탑이에요."},{"ko":"마샬 필드 스토어","en":"","say":"헨리 홉슨 리처드슨이 시카고에 지은 상업 건물(1887)","more":"거친 돌을 쌓고 큰 아치 창을 규칙적으로 반복했어요."},{"ko":"플랫아이언 빌딩","en":"","say":"1902년 뉴욕에 지어진 22층 고층 건물","more":"슬라이드는 리라이언스 빌딩(1895, 16층)과 나란히 놓아 높이 경쟁을 보여 줘요."},{"ko":"시카고 빌딩","en":"","say":"시카고 창과 3부분 분할을 한눈에 보여 주는 1905년 건물","more":"Chicago Building, 1905. 시카고 학파 고층건물의 특징 정리에 쓰이는 사례예요."},{"ko":"록펠러 센터","en":"","say":"레이먼드 후드가 1939년 미국 뉴욕에 지은 건물","more":"아르데코 마천루 사례로 슬라이드에 함께 실려 있어요."},{"ko":"엠파이어 스테이트 빌딩","en":"","say":"슈리브, 램 앤 하먼이 1931년 미국 뉴욕에 지은 마천루"},{"ko":"리글리 빌딩","en":"","say":"그레이엄, 앤더슨 앤 프로브스트 앤드 화이트가 1924년 시카고에 지은 건물","more":"흰 테라코타로 덮인 시계탑이 있는 마천루예요."},{"ko":"시카고 템플 빌딩","en":"","say":"올러버드 앤드 로시가 1924년 미국 시카고에 지은 건물","more":"꼭대기에 교회 첨탑 모양이 올라간 마천루예요."},{"ko":"안토니 가우디","en":"Antoni Gaudi","say":"3차원 곡선과 특이한 장식을 쓴 바르셀로나 건축가","more":"1852-1926. 중세건축의 영향, 벽돌과 석재, 표현주의적, 초현실주의의 선조. 강의자료 표기는 Antoni Gaudi. 통상 표기는 악센트를 붙인 Antoni Gaudí."},{"ko":"프리패브","en":"Prefabrication","say":"규격화된 부재를 현장에서 조립하는 공법","more":"만국박람회 건축의 빠른 조립, 해체 요구가 그 출발점."},{"ko":"찰스 레니 매킨토시","en":"Charles Rennie Mackintosh","say":"곡선에서 기하학적이고 간결한 양식으로 옮겨 간 스코틀랜드 건축가","more":"1868-1928. 수채화 화가이기도 함. 호프만의 사각형에 영향."},{"ko":"힐하우스","en":"Hill House","say":"회벽, 급경사 슬레이트 지붕, 반원형 탑을 지닌 매킨토시 주택(1904)","more":"평면 주요부와 서비스 윙이 직각 배치, 그리드로 분할된 개구부."},{"ko":"카사 바트요","en":"Casa Batllo","say":"중앙 코트와 구부러진 벽으로 방을 만든 가우디 작품(1906)","more":"강의자료 표기는 Casa Batllo. 통상 표기는 악센트를 붙인 Casa Batlló."},{"ko":"홈 인슈어런스 빌딩","en":"Home Insurance Building","say":"철골조와 커튼월로 지은 대표적 초기 철골조 건물(1885)","more":"윌리엄 제니. 1931년 철거."},{"ko":"모나드녹 빌딩","en":"Monadnock building","say":"1층 벽두께 1.8m 조적조에 장식을 뺀 존 루트의 건물(1893)","more":"'장식을 다용하는 것은 불필요하며 악덕이다'. 강의자료 표기는 b가 소문자인 Monadnock building. 통상 표기는 Monadnock Building."},{"ko":"웨인라이트 빌딩","en":"Wainwright Building","say":"세로줄로 수직성을 강조한 설리번 1단계 11층 철골 건물(1891)","more":"세인트루이스. 격자 파사드, 프리캐스트 테라코타 장식."},{"ko":"트리뷴 타워","en":"Tribune Tower","say":"시카고 트리뷴 사옥 공모전 당선작으로 1925년 완공된 건물","more":"후드와 하우얼스 안. 로스는 1922년 거대한 도리아식 기둥 형태를 제출."}],"3":[{"ko":"링 슈트라세","en":"","say":"쇼르스케가 문화적 선언이라 부른 빈의 도시 미화 사업","more":"신흥 중산계층을 위한 부르주아 아파트가 들어섬."},{"ko":"임페리얼 스타일","en":"Imperial style","say":"황제 왕정 문화 아래 빈이 선호한 전통 양식","more":"르네상스 및 바로크 양식과 함께 언급됨. 관료적, 보수적 성향."},{"ko":"역사주의","en":"","say":"과거 고전 형상에서 영감을 얻어 양식을 되풀이하는 태도","more":"바그너는 합리적 도시 문명을 위해 역사주의를 격퇴해야 한다고 주장."},{"ko":"총체예술","en":"Total Art","say":"건물부터 가구, 문손잡이까지 하나의 통일된 앙상블로 만드는 개념","more":"건축과 통합된 인테리어 개념 등장, 가구 제작자가 예술가 지위를 얻음. 목표는 라움쿤스트."},{"ko":"요제프 호프만","en":"","say":"사각형 요소를 반복해 사각형의 호프만이라 불린 총체예술 건축가","more":"1870-1956. 장르 구분과 서열을 부정, 대량생산 반대. 부유층 대상의 값비싼 디자인이 한계. 로스와 대척점."},{"ko":"푸커스도르프 요양원","en":"","say":"기하학적 바닥 패턴을 쓴 호프만의 오스트리아 요양원(1905)"},{"ko":"스토클레 저택","en":"","say":"호프만의 사각형과 클림트 모자이크가 어우러진 브뤼셀 저택(1911)","more":"모든 디자인이 통합된 심포니 같은 건축. 모자이크는 대리석, 유리, 준보석."},{"ko":"대위법","en":"","say":"직선 사각형과 소용돌이 곡선이 대비되며 서로 보완하는 구성","more":"스토클레 저택에서 호프만의 사각형과 클림트의 곡선."},{"ko":"빈 분리파","en":"Wiener Secession","say":"1897년 클림트가 기성 예술에 반기를 들며 결성한 조직","more":"제체시온. 미술과 생활의 새 관계 모색, 예술가 개인 존중, 장르 구분 폐지."},{"ko":"구스타프 클림트","en":"","say":"빈 분리파를 이끈 화가, 베토벤 프리즈와 스토클레 모자이크를 제작"},{"ko":"요제프 마리아 올브리히","en":"","say":"분리파 전시관과 다름슈타트 예술가회관을 지은 건축가","more":"빈과 다름슈타트를 오감. 작품 순서: 분리파 전시관(1898), 예술가회관(1901), 결혼기념탑(1905), 글뤼커트 주택(1911)."},{"ko":"분리파 전시관","en":"","say":"'각 시대에는 고유한 예술을, 예술에는 자유를' 표어를 단 건물(1898)","more":"올브리히 설계, 클림트 주도로 건립. 금색 월계수 잎 돔."},{"ko":"베토벤 프리즈","en":"","say":"클림트가 분리파 전시관 지하 전시장에 제작한 작품"},{"ko":"성스러운 봄","en":"Ver Sacrum","say":"분리파 전시관 측면에 새긴 문구"},{"ko":"뱀 머리 부적","en":"","say":"회화, 조각, 건축을 뜻하며 낡은 정신을 몰아내는 상징","more":"분리파 전시관 장식."},{"ko":"오토 바그너","en":"Otto Wagner","say":"'필요만이 예술의 주인'이라 한 빈의 합리적 기능주의 건축가","more":"1841-1918. '실용적이지 않은 것은 아름다울 수 없다'. 작품 순서 앙커하우스(1895), 마욜리카하우스(1898), 칼스플라츠 역사(1901), 우편저축은행(1906), 노이슈티프트가세(1911)."},{"ko":"칼스플라츠 역사","en":"","say":"오토 바그너가 설계한 빈의 역사(1901)"},{"ko":"마욜리카하우스","en":"","say":"풍화에 강하고 씻기 쉬운 식물 문양 타일로 덮은 바그너 주거블록(1898)","more":"위생을 고려한 재료 선택이 근대적 포인트. 표면이 구조와 분리."},{"ko":"링케 빈 차일레","en":"","say":"저층부 수평 띠로 투시도 효과를 극대화한 바그너 주거블록(1898)"},{"ko":"각 층 평준화","en":"","say":"엘리베이터 덕분에 층마다 층고를 동일하게 산정한 구성","more":"마욜리카하우스와 링케 빈 차일레의 특징."},{"ko":"우편저축은행","en":"","say":"장식 없이 형태와 구조만으로 이룬 최초의 진정한 근대 인테리어(1906)","more":"빈. 노출 메탈과 유리 배럴 보울트 지붕, 리벳 노출 금속 기둥, 구조용 유리 바닥, 근대적 네이브와 아일."},{"ko":"배럴 보울트 지붕","en":"","say":"우편저축은행 주 업무실을 덮은 노출 메탈과 유리 지붕"},{"ko":"구조용 유리 바닥","en":"","say":"빛이 지하로 투과하도록 유리로 만든 우편저축은행 바닥"},{"ko":"아르 누보","en":"Art Nouveau","say":"과거 양식 대신 자연의 곡선으로 새 양식을 만든 예술 사조","more":"프랑스어로 새로운 미술. 1890-1910, 최고조 1890-1905. '예술에는 일정한 형식이 없다'. 비대칭, 철과 유리, 공간보다 표면과 장식."},{"ko":"장식물","en":"ornament","say":"벽 자체가 조각처럼 기능하는 바로크식 입체 장식","more":"올브리히와 바그너는 ornament가 아니라 decoration을 택함."},{"ko":"치장","en":"decoration","say":"밋밋한 벽에 2차원 마감재를 덧입히는 면 처리"},{"ko":"앙커하우스","en":"","say":"바그너가 1895년 빈에 지은 상업 겸용 건물","more":"슬라이드에는 평면도와 거리 쪽 파사드 사진이 함께 나와요. 바그너 작품 중 가장 이른 시기예요."},{"ko":"아돌프 로스","en":"Adolf Loos","say":"장식을 타락이라 비난하고 라움플란을 쓴 빈 건축가","more":"1870-1933. 제체시온의 심미적 경향을 비판. 작품 순서 카페 무제움, 아메리칸 바(1908), 슈타이너(1910), 로스하우스(1912), 슈트라서(1918), 뮐러(1930)."},{"ko":"장식과 죄악","en":"Ornament und Verbrechen","say":"장식은 쓸모없는 타락의 표현이라 한 로스의 1908년 논문","more":"장식이 기계화된 생산방법에 맞지 않는다는 견해가 20세기 디자인의 중심이 됨."},{"ko":"아메리칸 바","en":"","say":"수직 거울로 대리석 천장을 비춰 공간을 넓혀 보이게 한 로스의 바(1908)","more":"돌출된 프리즘형 색유리 현관, 대리석 벽기둥 4개."},{"ko":"로스하우스","en":"","say":"장식 없는 외관 때문에 곡물창고라 조롱받은 로스의 빈 건물(1912)","more":"골트만 운트 잘라치 빌딩. 하부 상업은 녹색 대리석, 상부 주거는 매끈한 회반죽."},{"ko":"카페 무제움","en":"","say":"로스의 빈 초기작 카페","more":"강의자료에는 1988로 표기되어 있으나 통상 1899년 작으로 알려짐."},{"ko":"라움플란","en":"Raumplan","say":"방마다 필요한 높이를 따로 주고 입체적으로 맞물리는 로스의 설계법","more":"'나는 평면, 입면, 단면이 아니라 공간을 설계한다'. 거실을 두 개 층으로 개방. 라움쿤스트와 구분."},{"ko":"슈타이너 하우스","en":"","say":"장식 없는 청교도적 디자인을 보인 로스의 빈 주택(1910)"},{"ko":"네이브와 아일","en":"","say":"가운데가 높고 양옆이 낮은 세 갈래 공간 구성","more":"원래 교회 본당의 구성이에요. 우편저축은행 메인 뱅킹 룸이 완전히 근대적인 방식의 네이브와 아일이에요."},{"ko":"노이슈티프트가세 공동주택","en":"","say":"바그너가 1911년 빈에 지은 공동주택","more":"바그너 작품 순서의 마지막이에요. 벽에는 바그너가 1912-1918년 이 집에서 살았다는 명판이 붙어 있어요."},{"ko":"스플릿 레벨","en":"split level","say":"한 층 안에서 바닥 높이를 반 층씩 어긋나게 두는 방식","more":"라움플란에서 가장 많이 쓰는 층고 조절 기법."},{"ko":"라움쿤스트","en":"Raumkunst","say":"공간 자체가 예술이 되는 수준, 총체예술의 목표","more":"Space Art. 로스의 라움플란(공간 설계법)과 헷갈리지 않게."},{"ko":"슈트라서 하우스","en":"","say":"라움플란을 적용한 로스의 빈 주택(1918)"},{"ko":"뮐러 하우스","en":"","say":"라움플란이 완성된 로스의 체코 프라하 주택(1930)","more":"외관은 순수 형태, 내부는 풍부한 장식과 다양한 바닥 높이."},{"ko":"비트겐슈타인 하우스","en":"","say":"철학자 루드비히 비트겐슈타인이 직접 지은 빈 주택(1929)"},{"ko":"역사주의","en":"Historism","say":"과거 고전 형상에서 영감을 얻어 양식을 되풀이하는 태도","more":"바그너는 합리적 도시 문명을 위해 역사주의를 격퇴해야 한다고 주장. 강의자료 표기는 Historism. 통상 영어 표기는 Historicism."},{"ko":"요제프 호프만","en":"Josef Hoffmann","say":"사각형 요소를 반복해 사각형의 호프만이라 불린 총체예술 건축가","more":"1870-1956. 장르 구분과 서열을 부정, 대량생산 반대. 부유층 대상의 값비싼 디자인이 한계. 로스와 대척점."},{"ko":"구스타프 클림트","en":"Gustav Klimt","say":"빈 분리파를 이끈 화가, 베토벤 프리즈와 스토클레 모자이크를 제작"},{"ko":"베토벤 프리즈","en":"Beethoven Frieze","say":"클림트가 분리파 전시관 지하 전시장에 제작한 작품"},{"ko":"아메리칸 바","en":"American Bar","say":"수직 거울로 대리석 천장을 비춰 공간을 넓혀 보이게 한 로스의 바(1908)","more":"돌출된 프리즘형 색유리 현관, 대리석 벽기둥 4개."},{"ko":"비트겐슈타인 하우스","en":"Haus Wittgenstein","say":"철학자 루드비히 비트겐슈타인이 직접 지은 빈 주택(1929)"},{"ko":"카페 무제움","en":"Café Museum","say":"로스의 빈 초기작 카페","more":"강의자료에는 1988로 표기되어 있으나 통상 1899년 작으로 알려짐."}],"4":[{"ko":"기계론적 세계관","en":"","say":"세상이 기계 부품처럼 정해진 규칙대로 움직인다고 보는 생각","more":"공간디자인에서는 기술의존적 합리주의 경향과 같은 맥락."},{"ko":"합리주의","en":"","say":"이성으로 현실의 모든 문제를 해결할 수 있다고 믿는 태도","more":"1765년 증기기관 발명을 계기로 바로크, 로코코를 배제하고 태동. 표현주의와 반대, 경제성 요구 충족."},{"ko":"모더니즘","en":"","say":"새 과학기술과 생활방식에 맞춰 모든 예술에 나타난 새 형태의 이름","more":"회화, 조각, 건축, 음악, 문학. 독일에서는 바우하우스가 대표."},{"ko":"신즉물주의","en":"","say":"기술문명 지향 편에 속하는 반 표현주의적 전위예술","more":"데 스테일의 신조형주의와 헷갈리지 않게."},{"ko":"국제주의 양식","en":"International Style","say":"히치콕과 존슨의 1932년 책으로 굳어진 새 양식의 이름","more":"책 이름은 '국제주의 양식 : 1922년 이후의 건축'. 용어를 먼저 쓴 사람은 그로피우스."},{"ko":"오귀스트 페레","en":"Auguste Perret","say":"철근콘크리트로 구조를 경쾌하게 표현한 프랑스 건축가","more":"1874-1954."},{"ko":"프랭클린가 아파트","en":"","say":"지지 부재와 비지지 부재를 드러내 자유로운 평면의 원조가 된 아파트(1903)","more":"페레, 파리. 캔틸레버, 개방적 저층부, 변형된 U자형 평면."},{"ko":"캔틸레버","en":"cantilever","say":"한쪽 끝만 고정하고 다른 끝은 받침 없이 내민 구조"},{"ko":"커튼월","en":"curtain wall","say":"무게를 받지 않고 뼈대에 커튼처럼 걸어 놓은 바깥벽"},{"ko":"AEG 터빈공장","en":"","say":"유리 커튼월과 그리스 신전 같은 육중한 모서리를 지닌 공장(1909)","more":"페터 베렌스, 베를린. 낭만적 고전주의와 기계의 합리성 결합. 내부는 아치형 트러스."},{"ko":"페터 베렌스","en":"","say":"AEG 터빈공장과 베렌스 주택을 설계한 독일 건축가","more":"1868-1940. 1898년 유겐트슈틸 그래픽도 디자인."},{"ko":"파구스 신발공장","en":"","say":"모서리에 기둥 없이 유리가 꺾여 돌아가는 공장(1911)","more":"발터 그로피우스, 알펠트. 기둥은 파사드 뒤로 후퇴. 히치콕은 1차 대전 이전 가장 진보적 작품이라 평가."},{"ko":"독일공작연맹","en":"Deutscher Werkbund","say":"예술, 산업, 공업, 상업을 모아 기계로 좋은 제품을 만들자는 단체","more":"모리스의 이상을 모델로 삼되 기계 양산을 수용. 공장 생산에 맞는 장식 없는 형식 강조. 1927년 바이센호프 주최."},{"ko":"유리전시관","en":"","say":"셰어바르트 소설에서 영감을 얻은 타우트의 1914년 쾰른 축제건축","more":"다면체 큐폴라, 채색 유리 모자이크. 고딕의 성당에서 미래의 성당으로."},{"ko":"파울 셰어바르트","en":"Paul Scheerbart","say":"'유리가 새 시대를 열 것이다'라고 한 소설 <유리건축>의 작가","more":"1914년 출간."},{"ko":"바우하우스","en":"Bauhaus","say":"1919년 그로피우스가 바이마르에 세운 예술과 기술 통합 조형 학교","more":"독일공작연맹 이념 계승. 바이마르(1919), 데사우(1925), 베를린(1932), 1933년 폐쇄."},{"ko":"발터 그로피우스","en":"Walter Gropius","say":"바우하우스를 세우고 초대 교장을 맡은 건축가","more":"1883-1969. 파구스 공장, 데사우 교사, 바이센호프 16-17번(조립화)."},{"ko":"한네스 마이어","en":"","say":"1928년 교장이 된 바우하우스 2대 학장","more":"1889-1954. 학장 순서 그마미."},{"ko":"미스 반 데어 로에","en":"Mies van der Rohe","say":"바우하우스 3대 학장이자 바이센호프 주거단지를 이끈 건축가","more":"1886-1969. 1930년 교장. 바이센호프 1-4번 4층 아파트."},{"ko":"요하네스 이텐","en":"Johannes Itten","say":"재료, 질감, 색을 먼저 공부하는 바우하우스 입문과정을 이끈 화가","more":"1888-1967. 1923년 떠나고 모홀리 나지가 옴."},{"ko":"바우하우스 선언문","en":"","say":"'미술가와 공예가 사이에 본질적 차이는 없다'고 밝힌 1919년 선언","more":"건축가, 조각가, 화가 모두 공예로 돌아가 차별 없는 새로운 장인의 길드를 만들자."},{"ko":"데사우 바우하우스 교사","en":"","say":"정면이 없고 공방동 유리 커튼월이 빛나는 그로피우스의 건물(1926)","more":"장식 없는 흰 벽, 띠창. 거대하게 빛나는 유리상자."},{"ko":"데 스테일","en":"De Stijl","say":"직선과 면, 3원색과 무채색만 쓰는 네덜란드 예술 운동","more":"1917년 로테르담의 잡지에서 시작. 창단선언: 자연과 대립하는 기계미학을 건축의 근본으로."},{"ko":"표현주의","en":"Expressionism","say":"실재를 예술가가 주관적으로 해석해 특이하고 극적인 형태로 드러내는 흐름","more":"합리주의의 반대편. 아르누보의 구조적 혁신과 유동성에서 영향. 한계는 수공예적, 비경제적."},{"ko":"윌리엄 모리스","en":"William Morris","say":"미술공예운동을 이끈 벽지, 직물 중심의 디자이너","more":"1834-1896. 식물, 꽃, 새 같은 자연 모티프."},{"ko":"미술공예운동","en":"Arts and Crafts Movement","say":"기계 생산에 반발해 수공예의 즐거움과 정직함을 되찾자는 운동","more":"1860-1900. 1888년 런던 전시회에서 Arts and Crafts Exhibition Society 이름 처음 사용. 비싸서 대중 수요를 못 채운 한계, 아르누보에 영향."},{"ko":"시-공간","en":"space-time","say":"유리 파사드를 따라 걸으며 중첩된 뷰를 경험하는 것","more":"지그프리드 기디온이 데사우 교사를 건축에서의 진정한 시-공간 적용 사례로 평가."},{"ko":"Housing Units","en":"","say":"기본 공간단위를 조합해 표준 주거타입을 만든 그로피우스의 1923년 제안","more":"생산 효율성과 거주자의 선택 가능성을 함께 보장."},{"ko":"마이스터 주택","en":"","say":"비용 절감과 공기 단축을 계산해 지은 바우하우스 교수들의 주택","more":"평지붕, 매끈한 벽체, 처마나 인방 없이 벽과 한 면을 이루는 창."},{"ko":"인방","en":"","say":"창 위에 가로로 걸친 부재"},{"ko":"국제주의 건축","en":"internationale Architektur","say":"그로피우스가 1925년 바우하우스 총서 1권 표제로 쓴 용어","more":"기능과 기술을 따르면 나라가 달라도 건물이 닮는다는 흐름."},{"ko":"기능주의","en":"Functionalism","say":"건물의 목적이 되는 사용과 기능을 형태가 그대로 표현하는 건축","more":"좋은 디자인의 미학은 특정 형태가 아니라 테크놀로지의 재현에 있음."},{"ko":"리처드 노이트라","en":"Richard Neutra","say":"로벨 하우스와 카우프만 저택을 지은 미국의 국제주의 건축가","more":"1892-1970."},{"ko":"로벨 하우스","en":"Lovell House","say":"대부분 카탈로그 부품으로 지은 노이트라의 강철 프레임 주택(1929)","more":"Health House라고도 함. 로스앤젤레스. 넓은 유리와 장식 없는 흰 벽."},{"ko":"카우프만 저택","en":"","say":"미스 반 데어 로에의 영향이 보이는 노이트라의 팜 스프링스 주택(1947)"},{"ko":"아돌프 로스","en":"Adolf Loos","say":"장식을 타락이라 비난하고 라움플란을 쓴 빈 건축가","more":"1870-1933. 제체시온의 심미적 경향을 비판. 작품 순서 카페 무제움, 아메리칸 바(1908), 슈타이너(1910), 로스하우스(1912), 슈트라서(1918), 뮐러(1930)."},{"ko":"신조형주의","en":"","say":"형태와 색의 추상적 가치가 우월하다는 몬드리안과 반 두스뷔르흐의 이론","more":"3차원 볼륨을 2차원의 면으로 환원."},{"ko":"피트 몬드리안","en":"Piet Mondrian","say":"직선과 무채색, 3원색만으로 화면을 구성한 데 스테일 화가","more":"1871-1944."},{"ko":"야코부스 J. P. 오우트","en":"Jacobus J. P. Oud","say":"카페 더 우니를 설계한 데 스테일 건축가","more":"1890-1963. 바이센호프에서는 5-9번 연립주택."},{"ko":"카페 더 우니","en":"","say":"파사드를 종횡 직선으로 나누고 원색을 칠한 로테르담 카페(1925)"},{"ko":"헤리트 리트펠트","en":"Gerrit Rietveld","say":"슈뢰더 하우스를 설계한 데 스테일 건축가","more":"1888-1964. 의뢰인은 트루스 슈뢰더."},{"ko":"슈뢰더 하우스","en":"","say":"판들이 3차원 좌표에 떠 있고 위층을 미닫이 판으로 나누는 주택(1924)","more":"위트레흐트. 칸막이벽으로 유동적 공간, 과감한 색상."},{"ko":"테오 반 두스뷔르흐","en":"Theo Van Doesburg","say":"데 스테일 형태에 대각선 요소를 더한 작가","more":"1883-1931."},{"ko":"카페 로베뜨","en":"l'Aubette","say":"수평 수직 위에 대각선을 조합한 스트라스부르 엔터테인먼트 센터 실내(1928)","more":"바, 무도회장, 시네마가 있는 복합 레스토랑. 2016년 복원."},{"ko":"아르 누보","en":"Art Nouveau","say":"과거 양식 대신 자연의 곡선으로 새 양식을 만든 예술 사조","more":"프랑스어로 새로운 미술. 1890-1910, 최고조 1890-1905. '예술에는 일정한 형식이 없다'. 비대칭, 철과 유리, 공간보다 표면과 장식."},{"ko":"합리주의","en":"Rationalism","say":"이성으로 현실의 모든 문제를 해결할 수 있다고 믿는 태도","more":"1765년 증기기관 발명을 계기로 바로크, 로코코를 배제하고 태동. 표현주의와 반대, 경제성 요구 충족."},{"ko":"역사주의","en":"Historism","say":"과거 고전 형상에서 영감을 얻어 양식을 되풀이하는 태도","more":"바그너는 합리적 도시 문명을 위해 역사주의를 격퇴해야 한다고 주장. 강의자료 표기는 Historism. 통상 영어 표기는 Historicism."},{"ko":"페터 베렌스","en":"Peter Behrens","say":"AEG 터빈공장과 베렌스 주택을 설계한 독일 건축가","more":"1868-1940. 1898년 유겐트슈틸 그래픽도 디자인."},{"ko":"브루노 타우트","en":"Bruno Taut","say":"표현주의를 옹호하고 색채를 잘 쓴 독일 건축가","more":"1880-1938. 유리전시관(1914), 바이센호프 19번, 후프아이젠 주거단지(1931)."},{"ko":"평지붕","en":"Flat Roof","say":"바이센호프 주택들이 공통으로 쓴 평평한 지붕"},{"ko":"카페 더 우니","en":"Cafe de Unie","say":"파사드를 종횡 직선으로 나누고 원색을 칠한 로테르담 카페(1925)","more":"도면 속 간판 글자가 CAFE DE UNIE. 통상 표기는 악센트를 붙인 Café De Unie."}],"5":[{"ko":"레드 빈","en":"Red Wien","say":"1920년대 이후 빈에서 정부보조로 노동자주택을 대규모로 지은 시대"},{"ko":"슈퍼블럭","en":"","say":"인간적 스케일을 넘는 대규모 중정형 주거 블록","more":"레드 빈 시대 집합주택의 구성."},{"ko":"인간적 스케일","en":"","say":"사람의 눈높이에서 느끼는 크기 감각"},{"ko":"중정","en":"","say":"건물이 빙 둘러싼 가운데의 큰 마당"},{"ko":"칼 마르크스 호프","en":"Karl Marx Hof","say":"길이 1km 블록에 1300세대를 담은 빈의 주거단지(1930)","more":"5-7층, 운동장, 탁아소, 세탁장, 병원, 도서관, 상점. 벽돌 2,500만 개, '작은 붉은 벽돌이 새로운 세계를 건설하다'. 표현주의적 색채와 강한 조형성."},{"ko":"카를 엔","en":"","say":"칼 마르크스 호프를 설계한 건축가"},{"ko":"바이센호프 주거단지","en":"Weissenhof Siedlung","say":"1927년 슈투트가르트에서 열린 근대건축가들의 주택전시회","more":"독일공작연맹 주최, 미스 반 데어 로에 주도. 장식 없는 벽, 평지붕, 자유로운 입면. CIAM 결성과 국제주의 확산의 계기."},{"ko":"선형 집합주택","en":"","say":"바이센호프 주거단지가 효시적 성격을 띤 집합주택 형식"},{"ko":"단위주택","en":"","say":"서민에게 제공하려 한 중간 규모의 주택","more":"바이센호프의 목표. 4층 아파트, 연립주택, 단독주택 등 다양한 유형."},{"ko":"필로티","en":"","say":"건물을 기둥으로 들어 올려 아래를 비우는 방식","more":"르 코르뷔지에가 바이센호프에서 개방적인 평면 개념과 함께 제시."},{"ko":"조립화","en":"","say":"바이센호프에서 그로피우스가 가능성을 제시한 건축 방식","more":"그로피우스는 16-17번 주택."},{"ko":"평지붕","en":"","say":"바이센호프 주택들이 공통으로 쓴 평평한 지붕"},{"ko":"르 코르뷔지에","en":"Le Corbusier","say":"바이센호프 13-15번에서 필로티와 개방적인 평면을 보여준 건축가"},{"ko":"피에르 잔느레","en":"Pierre Jeanneret","say":"르 코르뷔지에와 함께 바이센호프 2호 연립주택을 설계한 건축가"},{"ko":"기능주의 주거건축","en":"","say":"철근콘크리트와 유리로 '기능적'으로 계획한 주거건축","more":"바이센호프 주거단지로 등장."},{"ko":"근대건축 국제회의","en":"CIAM","say":"바이센호프를 계기로 결성된 근대건축가들의 국제 모임","more":"주요 목표: '주택-단지-도시계획', '합리적 계획'과 '표준화'."},{"ko":"합리적 계획과 표준화","en":"","say":"CIAM이 공동 활동의 주제로 내건 두 가지 방법"},{"ko":"획일화","en":"","say":"역사적 연속성을 간과해 어디나 같은 집이 된 근대 주거의 단점","more":"지역적, 문화적 특수성을 수용하지 못하는 보편적, 평균적 주거로 변모. 반면 장점은 주거의 양적 부족현상 개선."},{"ko":"평균적 인간을 위한 평균적 주거","en":"","say":"근대건축의 주거유형을 요약한 말","more":"하나의 전형이 되어 세계화, 보편화됨."},{"ko":"공업화건축","en":"","say":"공장생산 방식으로 주택을 짓는 근대건축의 생산 방식","more":"공장생산의 패러다임이 장식과 미적 요소에도 반영됨."},{"ko":"국제주의 세 가지 부재","en":"","say":"역사성, 국가적 소속, 맥락이 없다는 국제주의 건축의 요약","more":"외우기: 역국맥."},{"ko":"균질성","en":"homogeneous","say":"효율성을 동반한 기술, 질서, 시스템과 함께 꼽힌 근대건축의 특징","more":"1970년대까지 지속된 기능주의와 국제주의의 특징. 외우기: 기질시균."},{"ko":"세 개의 동심원","en":"","say":"개인, 민족, 인류 중 인류가 나머지 둘을 포함한다는 그로피우스의 비유"},{"ko":"루이스 멈퍼드","en":"","say":"과학과 기술로 인간이 기계에 적응해야 하는 시대가 됐다고 본 인물","more":"강의자료 표기는 L. 멈퍼드(Lewis Munford)."},{"ko":"독일공작연맹","en":"Deutscher Werkbund","say":"예술, 산업, 공업, 상업을 모아 기계로 좋은 제품을 만들자는 단체","more":"모리스의 이상을 모델로 삼되 기계 양산을 수용. 공장 생산에 맞는 장식 없는 형식 강조. 1927년 바이센호프 주최."},{"ko":"미스 반 데어 로에","en":"Mies van der Rohe","say":"바우하우스 3대 학장이자 바이센호프 주거단지를 이끈 건축가","more":"1886-1969. 1930년 교장. 바이센호프 1-4번 4층 아파트."},{"ko":"발터 그로피우스","en":"Walter Gropius","say":"바우하우스를 세우고 초대 교장을 맡은 건축가","more":"1883-1969. 파구스 공장, 데사우 교사, 바이센호프 16-17번(조립화)."},{"ko":"야코부스 J. P. 오우트","en":"Jacobus J. P. Oud","say":"카페 더 우니를 설계한 데 스테일 건축가","more":"1890-1963. 바이센호프에서는 5-9번 연립주택."},{"ko":"국제주의 양식","en":"International Style","say":"히치콕과 존슨의 1932년 책으로 굳어진 새 양식의 이름","more":"책 이름은 '국제주의 양식 : 1922년 이후의 건축'. 용어를 먼저 쓴 사람은 그로피우스."},{"ko":"슈퍼블럭","en":"Superblock","say":"인간적 스케일을 넘는 대규모 중정형 주거 블록","more":"레드 빈 시대 집합주택의 구성."},{"ko":"인간적 스케일","en":"Human Scale","say":"사람의 눈높이에서 느끼는 크기 감각"},{"ko":"중정","en":"Courtyard","say":"건물이 빙 둘러싼 가운데의 큰 마당"},{"ko":"카를 엔","en":"Karl Ehn","say":"칼 마르크스 호프를 설계한 건축가"},{"ko":"평지붕","en":"Flat Roof","say":"바이센호프 주택들이 공통으로 쓴 평평한 지붕"},{"ko":"필로티","en":"Pilotis","say":"건물을 기둥으로 들어 올려 아래를 비우는 방식","more":"르 코르뷔지에가 바이센호프에서 개방적인 평면 개념과 함께 제시."},{"ko":"획일화","en":"Uniformity","say":"역사적 연속성을 간과해 어디나 같은 집이 된 근대 주거의 단점","more":"지역적, 문화적 특수성을 수용하지 못하는 보편적, 평균적 주거로 변모. 반면 장점은 주거의 양적 부족현상 개선."},{"ko":"루이스 멈퍼드","en":"Lewis Munford","say":"과학과 기술로 인간이 기계에 적응해야 하는 시대가 됐다고 본 인물","more":"강의자료 표기는 L. 멈퍼드(Lewis Munford). 통상 표기는 Lewis Mumford."}],"6":[{"ko":"표현주의","en":"Expressionism","say":"실재를 예술가가 주관적으로 해석해 특이하고 극적인 형태로 드러내는 흐름","more":"합리주의의 반대편. 아르누보의 구조적 혁신과 유동성에서 영향. 한계는 수공예적, 비경제적."},{"ko":"환상주의 건축","en":"","say":"표현주의 건축의 다른 이름, 이상주의 건축이라고도 함","more":"샤로운 시기에는 국제주의의 단조로움과 빈곤한 창작력에 반발한 건축을 가리킴."},{"ko":"베를린 분리파전","en":"","say":"1911년 표현주의라는 용어가 처음 쓰인 회화 전시"},{"ko":"향토양식","en":"","say":"지역적 특색을 표현한 양식, 1920-30년대 표현주의가 계승","more":"특히 독일 북부와 네덜란드에서 발달."},{"ko":"브루노 타우트","en":"Bruno Taut","say":"표현주의를 옹호하고 색채를 잘 쓴 독일 건축가","more":"1880-1938. 유리전시관(1914), 바이센호프 19번, 후프아이젠 주거단지(1931)."},{"ko":"필연성","en":"Eine Notwendigkeit","say":"건축은 형식과 내용 모두 유용해야 한다고 한 타우트의 1914년 논문","more":"표현주의를 옹호한 최초의 성명."},{"ko":"후프아이젠 주거단지","en":"","say":"타우트의 색채디자인이 드러난 베를린 주거단지(1931)"},{"ko":"센테니얼 홀","en":"","say":"노출 콘크리트 구조체가 조각처럼 일체적인 막스 베르크의 홀(1913)","more":"폴란드 브로츠와프(당시 독일 브레슬라우). 표현을 장식 대신 구조요소로 해결해 고딕정신에 가까움."},{"ko":"막스 베르크","en":"","say":"센테니얼 홀을 설계한 건축가"},{"ko":"아인슈타인 타워","en":"","say":"파도에서 솟은 잠수함 잠망경 같은 멘델존의 전망대(1921)","more":"포츠담. 깊게 파인 곡면 창, 벽돌에 콘크리트를 덧씌움."},{"ko":"에리히 멘델존","en":"","say":"콘크리트의 조소성으로 빛과 그림자를 극적으로 연출한 건축가","more":"'재료를 작품으로 만드는 직관'. 쇼켄 백화점 스케치(1928)."},{"ko":"조소성","en":"","say":"굳기 전 찰흙처럼 모양을 빚을 수 있는 콘크리트의 성질"},{"ko":"쇼켄 백화점 스케치","en":"","say":"멘델존이 1928년 남긴 백화점 디자인 스케치"},{"ko":"에른스트 루드비히 키르히너","en":"","say":"표현주의 회화 사례로 소개된 화가(1914)"},{"ko":"암스테르담파","en":"","say":"네덜란드의 값싼 전통재료 벽돌로 재료 특성을 표현한 표현주의 흐름","more":"그로피우스의 국제주의 양식에 밀려 단명."},{"ko":"에이흔 하르드","en":"Eigen Haard","say":"미씰 더 클러르크가 설계한 암스테르담 집합주택(1919)","more":"현재 Het Schip Museum."},{"ko":"미씰 더 클러르크","en":"","say":"에이흔 하르드를 설계한 암스테르담파 건축가"},{"ko":"북부 독일의 벽돌구조 고딕","en":"","say":"함부르크 표현주의가 이어받은 한자동맹 도시의 벽돌건축 전통"},{"ko":"칠레하우스","en":"","say":"벽돌 각기둥을 빽빽이 나열한 듯한 파사드의 함부르크 복합건물(1924)","more":"프리츠 회거. 주거, 상업, 사무소 복합. 지방색이 강한 근대 사무소 건축. 2002년 개보수."},{"ko":"프리츠 회거","en":"","say":"칠레하우스와 스프링켄호프를 지은 함부르크 건축가"},{"ko":"스프링켄호프","en":"","say":"프리츠 회거의 함부르크 사무소 건물(1927)"},{"ko":"합리주의","en":"","say":"이성으로 현실의 모든 문제를 해결할 수 있다고 믿는 태도","more":"1765년 증기기관 발명을 계기로 바로크, 로코코를 배제하고 태동. 표현주의와 반대, 경제성 요구 충족."},{"ko":"국제주의 양식","en":"International Style","say":"히치콕과 존슨의 1932년 책으로 굳어진 새 양식의 이름","more":"책 이름은 '국제주의 양식 : 1922년 이후의 건축'. 용어를 먼저 쓴 사람은 그로피우스."},{"ko":"유리전시관","en":"","say":"셰어바르트 소설에서 영감을 얻은 타우트의 1914년 쾰른 축제건축","more":"다면체 큐폴라, 채색 유리 모자이크. 고딕의 성당에서 미래의 성당으로."},{"ko":"발터 그로피우스","en":"Walter Gropius","say":"바우하우스를 세우고 초대 교장을 맡은 건축가","more":"1883-1969. 파구스 공장, 데사우 교사, 바이센호프 16-17번(조립화)."},{"ko":"아르 누보","en":"Art Nouveau","say":"과거 양식 대신 자연의 곡선으로 새 양식을 만든 예술 사조","more":"프랑스어로 새로운 미술. 1890-1910, 최고조 1890-1905. '예술에는 일정한 형식이 없다'. 비대칭, 철과 유리, 공간보다 표면과 장식."},{"ko":"베델 주거단지","en":"","say":"개구부 주변 벽돌 요철로 수공예적 특성을 드러낸 함부르크 단지(1931)","more":"1층 벽돌 아치, 45도 사선 돌출부, 마름모꼴 작은 창."},{"ko":"프리츠 슈마허","en":"","say":"베델 주거단지를 설계한 함부르크 건축가"},{"ko":"한스 샤로운","en":"Hans Scharoun","say":"국제주의에 반발해 표현주의를 되살린 베를린 필하모니 홀의 건축가","more":"1893-1972. 바이센호프 33번 주택, 국립도서관(1978)."},{"ko":"베를린 필하모니 홀","en":"","say":"청중이 가운데 연주자를 둘러싸는 샤로운의 공연장(1963)","more":"디자인 모토 'Focus on Music'. 로비는 홀 매스 아래의 흐르는 공간."},{"ko":"Tribune Segment","en":"","say":"필하모니 홀 청중석을 나눈 부정형의 작은 공간 단위","more":"덩굴이 늘어진 테라스에 비유. 친밀한 관계와 우수한 음향."},{"ko":"동심공간 코어","en":"","say":"연주 홀을 중심에 둔 필하모니 홀의 공간 구성"},{"ko":"국립도서관","en":"","say":"한스 샤로운이 설계한 베를린 도서관(1978)"},{"ko":"국제주의 건축","en":"internationale Architektur","say":"그로피우스가 1925년 바우하우스 총서 1권 표제로 쓴 용어","more":"기능과 기술을 따르면 나라가 달라도 건물이 닮는다는 흐름."},{"ko":"스프링켄호프","en":"Sprinkenhof","say":"프리츠 회거의 함부르크 사무소 건물(1927)","more":"강의자료 한글은 스프링켄호프지만 사진 속 건물 글자는 g가 없는 SPRINKENHOF. 카드 영문은 사진 표기를 따랐어요."},{"ko":"국립도서관","en":"Staatsbibliothek zu Berlin","say":"한스 샤로운이 설계한 베를린 도서관(1978)"}],"7":[{"ko":"르 코르뷔지에","en":"Le Corbusier","say":"기능주의와 표현주의를 합친 국제주의 건축 제 1세대 건축가","more":"1887-1965. 거친 마감 콘크리트 사용을 연구한 최초의 건축가, 중앙유럽, 인도, 러시아, 미국 등지에 건물을 세운 도시계획가. 슬라이드에는 르 꼬르뷔지에, 르 꼬르뷔제로도 적혀 있어요."},{"ko":"국제주의 건축의 제 1세대","en":"","say":"국제주의 건축을 처음 연 세대. 르 코르뷔지에가 여기에 속함","more":"슬라이드 소개: 당시 기능주의자들의 열망과 표현주의적인 강렬한 감각을 결합."},{"ko":"브루탈리즘","en":"","say":"거친 콘크리트를 그대로 드러내는 건축 흐름. 르 코르뷔지에가 발전시킴","more":"슬라이드의 세 키워드: 브루탈리즘의 발전, 인본적 디자인 방식, 주거와 도시설계에 대한 영향력."},{"ko":"인본적 디자인 방식","en":"","say":"사람을 중심에 둔 르 코르뷔지에의 디자인 태도","more":"사람 몸 치수에서 뽑은 모듈러와 이어서 기억해요."},{"ko":"에스프리 누보","en":"L'Esprit Nouveau","say":"'새로운 정신'이라는 뜻의 잡지. 1920년 1월 창간","more":"르 코르뷔지에, 오장팡 등이 함께 참여. 미술, 문학, 과학, 건축에 관한 새로운 사상과 이론을 담음."},{"ko":"오장팡","en":"","say":"르 코르뷔지에와 함께 잡지 에스프리 누보를 창간한 사람","more":"1920년 1월 창간. 슬라이드 그림 속 설명글에만 나와요."},{"ko":"건축을 향하여","en":"Vers une Architecture","say":"르 코르뷔지에가 1923년에 낸 건축 선언의 책","more":"세상에 대한 분명한 선언과 자기 건축작품에 담은 개념을 설명. 젊은 날의 진취적이고 개혁적인 생각을 담음."},{"ko":"에스쁘리 누보 전시관","en":"","say":"1925년 파리 장식 미술 전시회에 지은 르 코르뷔지에의 전시관","more":"자기 이론대로 디자인한 모델 아파트 인테리어를 보여 줌. 잡지 이름은 '에스프리 누보'로 적혀 있어 표기가 달라요."},{"ko":"순수주의","en":"","say":"르 코르뷔지에가 주장한 그림 스타일. 단순한 모양으로 사물을 그림","more":"에스쁘리 누보 전시관 벽에 걸린 예술 작품들이 순수주의 스타일의 전형."},{"ko":"벤트우드 체어","en":"","say":"나무를 구부려 만든 토네트의 의자","more":"에스쁘리 누보 전시관에 모듈러 스토리지 유닛, 단순한 암 체어와 함께 놓임. 당시 장식적인 가구들과 차별성이 있는 가구."},{"ko":"모듈러 스토리지 유닛","en":"","say":"같은 치수 단위로 짜 맞춘 수납 가구","more":"에스쁘리 누보 전시관(1925)의 가구. 장식적인 가구의 표준과 다른 새 가구로 제안."},{"ko":"모듈러","en":"Modulor","say":"사람 몸 치수에서 뽑은 르 코르뷔지에의 비례 체계","more":"규준선을 설계 단계부터 미리 쓰려는 생각에서 출발. 유니테 다비타시옹의 척도 조정, 르 코르뷔지에 센터의 모든 요소 통제에 사용. 회상 '모듈러' 1950."},{"ko":"규준선","en":"","say":"완성된 건물의 비례를 검증하는 기준선","more":"르 코르뷔지에는 규준선을 건축설계 단계부터 미리 적용하려 했고, 이 생각이 모듈러 발명의 계기가 됨. 그의 정물화 속 규준선은 편안한 비례로 균형감을 줌."},{"ko":"아인슈타인과의 만남","en":"","say":"프린스턴에서 아인슈타인에게 모듈러를 설명한 일화","more":"그날 밤 아인슈타인의 편지: '악을 어렵게 하고 선을 쉽게 만들어내는 것이 바로 비례라는 척도'. 르 코르뷔지에의 회상 '모듈러' 1950."},{"ko":"단위주거","en":"","say":"도시를 이루는 집 한 칸 단위","more":"르 코르뷔지에 건축의 특징 두 줄: 도시라는 맥락 안에서 단위주거를 설계, 단위주거에서 출발하여 도시를 설계."},{"ko":"인구 300만의 현대도시","en":"Une Ville Contemporaine","say":"르 코르뷔지에의 1922년 도시계획 이론","more":"도심으로의 인구 집중에 대비해 도시 지역을 적극 개발, 고층건물 제시, 교통문제 고려. 그림 속 이름 '현대도시 빌 콘템포레느(1922)'."},{"ko":"십자형의 사무소 타워","en":"","say":"현대도시 계획안 한가운데 늘어선 십자 모양 고층 사무소","more":"현대도시 계획안(1922) 그림 속 글자."},{"ko":"르 꼬르뷔지에의 이상적 도시","en":"","say":"과거 도시 구조를 버리고 주거, 일터, 여가공간, 교통망으로 짠 도시","more":"과거의 도시공간구조 거부. 도심 인구 집중에 대비해 도시 지역을 적극 개발."},{"ko":"복층","en":"","say":"한 집이 위아래 두 층을 함께 쓰는 구성","more":"현대도시의 주택(복층의 생활공간), 시트로앵 하우스, 유니테 다비타시옹(중복도와 복층주택)에 계속 나와요."},{"ko":"옥외공간","en":"","say":"집에 딸린 바깥 공간","more":"현대도시에서의 주택: 복층의 생활공간과 개인적인 옥외공간 제공."},{"ko":"평지붕","en":"Flat Roof","say":"경사 없이 평평한 지붕","more":"현대도시의 주택은 발코니와 옥상정원을 든 평지붕의 주택. 영어 5원칙 1번 Flat Roof/Roof Garden."},{"ko":"옥상정원","en":"Roof Garden","say":"평지붕 위에 만든 정원","more":"건축의 5원칙 3번(한국어 목록). 영어 목록에서는 1번 Flat Roof/Roof Garden."},{"ko":"필로티","en":"Pilotis","say":"건물을 기둥으로 들어 올려 아래를 비우는 방식","more":"5원칙 2번(한국어 목록), 4번(영어 목록). 빌라 사보아, 시트로앵 하우스, 유니테 다비타시옹의 거대한 필로티."},{"ko":"살기 위한 기계","en":"","say":"집을 기계처럼 효율적이고 어디서나 통하게 만들자는 생각","more":"인간의 기본욕구를 만족시키는 합리적인 설계 제안: 효율적인 기능과 지역에 관계없는 보편성 추구."},{"ko":"건축의 5원칙","en":"Five Points of Architecture","say":"르 코르뷔지에가 정리한 새 집 짓기 규칙 다섯 가지","more":"한국어 목록: 뼈대와 벽의 기능적 분리, 필로티, 옥상정원, 자유로운 평면, 자유로운 입면. 영어 목록: Flat Roof/Roof Garden, Freed Facade, Ribbon Windows, Pilotis, Open Plan."},{"ko":"뼈대와 벽의 기능적 분리","en":"","say":"짐은 기둥 뼈대가 지고 벽은 칸막이만 하게 나누는 것","more":"건축의 5원칙 1번(한국어 목록). 영어 목록에는 이 항목 대신 Ribbon Windows가 있어요."},{"ko":"자유로운 평면","en":"Open Plan","say":"벽이 짐을 안 지니 방 배치를 마음대로 하는 평면","more":"5원칙 4번(한국어), 5번(영어). 라 투레트 수도원의 집회실 및 식당도 자유로이 개방된 평면."},{"ko":"자유로운 입면","en":"Freed Facade","say":"벽이 짐을 안 지니 겉면 창과 벽을 마음대로 짜는 입면","more":"5원칙 5번(한국어), 2번(영어)."},{"ko":"수평띠창","en":"Ribbon Windows","say":"건물 옆으로 길게 이어 붙인 띠 모양 창","more":"영어 5원칙 3번. 빌라 사보아 '연속된 수평띠창', 흰 주택 '수평으로 연속된 창'."},{"ko":"철근 콘크리트","en":"","say":"철근을 넣어 굳힌 콘크리트. 르 코르뷔지에가 새 재료로 완전히 활용","more":"철근 콘크리트라는 새로운 재료의 이용과 그 구조적, 미학적 가능성을 완전히 활용한 형태 추구."},{"ko":"도미노 시스템","en":"Dom-ino","say":"기둥과 바닥판만으로 짠 집의 뼈대","more":"Domus 집 + Innovation 혁신 = dom-ino. 자동차 뼈대 구조에서 아이디어. 기둥골조 여섯 개, 바닥슬래브 두 개, 지붕. 모든 주거계획의 원형. 흰 주택에서 기둥간격 5미터 그리드."},{"ko":"융통성","en":"","say":"실내구획과 외벽 위치를 마음대로 바꿀 수 있는 여유","more":"도미노 시스템이 실내구획과 외벽의 위치에 융통성을 부여."},{"ko":"시트로앵 하우스","en":"","say":"도미노 주택의 실제 모델로 제시된 1924년 주택","more":"단순한 상자모양, 옥상지붕, 상하층으로 분리된 거실, 넓은 전면창, 필로티, 복층. 대량생산 개념. 1920, 30년대 주거계획의 기본형식. 캡션은 '시트로앵주택'."},{"ko":"대량생산","en":"","say":"같은 물건을 공장에서 한꺼번에 많이 만드는 것","more":"시트로앵 하우스는 대량생산의 개념에 따라 제시된 주택."},{"ko":"흰 주택","en":"","say":"1920년대 르 코르뷔지에가 지은 하얀 상자 모양 주택들","more":"La Roche-Jeanneret 저택, Masion Cook, Garches의 집(메종 스테인), Stuttgart의 주택 등. 공통 공간구성이 있어요."},{"ko":"순수직방체","en":"","say":"군더더기 없는 단순한 상자 모양","more":"흰 주택: 수평으로 연속된 창, 단순한 상자형태(순수직방체)."},{"ko":"","en":"Void","say":"건물 안에 위아래로 비워 둔 빈 공간","more":"흰 주택: Void와 테라스의 비대칭적 배치로 내부 공간의 편심. 계단과 경사로가 Void 및 테라스와 호응(sequence)."},{"ko":"편심","en":"","say":"공간의 중심이 한쪽으로 치우친 것","more":"Void와 테라스의 비대칭적 배치가 만드는 내부 공간의 편심."},{"ko":"경사로","en":"","say":"계단 대신 비탈길로 오르내리는 길","more":"흰 주택에서 계단과 경사로가 Void 및 테라스와 호응. 빌라 사보아는 지붕까지 계속되는 실내의 경사."},{"ko":"황금분할","en":"","say":"가장 아름답다고 여겨 온 비례 나누기","more":"메종 스테인 입면 그림에 '황금분할에 기초한 비례 관계'라고 적혀 있어요."},{"ko":"메종 스테인","en":"Villa Garches","say":"가르슈의 집. 1928년 파리 근교의 흰 주택","more":"슬라이드 캡션 1928. 그림 속 메모 '황금분할에 기초한 비례 관계', '2층 높이의 테라스'."},{"ko":"","en":"Masion Cook","say":"1926년 프랑스 파리의 흰 주택 메종 쿡","more":"슬라이드 철자 Masion은 Maison(메종)의 오타로 보여요. 평면 Basement, First Floor, Second Floor, Terrace."},{"ko":"","en":"Villa La Roche Jeanneret","say":"1924년 프랑스 파리의 흰 주택","more":"흰 주택 목록에서는 'La Roche-Jeanneret 저택'. 곡면 벽 위 수평창, 기둥으로 들어 올린 부분이 보여요."},{"ko":"기능주의","en":"Functionalism","say":"건물의 목적이 되는 사용과 기능을 형태가 그대로 표현하는 건축","more":"좋은 디자인의 미학은 특정 형태가 아니라 테크놀로지의 재현에 있음."},{"ko":"표현주의","en":"Expressionism","say":"실재를 예술가가 주관적으로 해석해 특이하고 극적인 형태로 드러내는 흐름","more":"합리주의의 반대편. 아르누보의 구조적 혁신과 유동성에서 영향. 한계는 수공예적, 비경제적."},{"ko":"바이센호프 주거단지","en":"Weissenhof Siedlung","say":"1927년 슈투트가르트에서 열린 근대건축가들의 주택전시회","more":"독일공작연맹 주최, 미스 반 데어 로에 주도. 장식 없는 벽, 평지붕, 자유로운 입면. CIAM 결성과 국제주의 확산의 계기."},{"ko":"","en":"LC4 Chaise Lounge","say":"르 코르뷔지에, 피에르 잔느레, 샤롯테 페리앙이 디자인한 누워 쉬는 의자","more":"라 로슈 잔느레 저택 쪽 슬라이드에 함께 나와요."},{"ko":"피에르 잔느레","en":"Pierre Jeanneret","say":"르 코르뷔지에와 함께 설계하고 가구를 디자인한 건축가","more":"바이센호프 주거단지 2호연립주택(1927), LC4 Chaise Lounge."},{"ko":"샤롯테 페리앙","en":"","say":"LC4 Chaise Lounge를 함께 디자인한 디자이너","more":"르 코르뷔지에, 피에르 잔느레와 공동 디자인."},{"ko":"바이센호프 주거단지 2호연립주택","en":"","say":"르 코르뷔지에와 피에르 잔느레의 1927년 슈투트가르트 연립주택","more":"5단원 바이센호프와 이어지는 작품. 평면 A, B, C 세 장."},{"ko":"빌라 사보아","en":"Villa Savoye","say":"1931년 프랑스 포와시에 지은 5원칙의 대표 주택","more":"백색의 단순한 입방체 2층 건물, 상층부에 주공간, 연속된 수평띠창, 필로티, 지붕까지 계속되는 실내의 경사. 슬라이드 한 곳은 Vila Savoye로 오타."},{"ko":"중정","en":"","say":"건물 안쪽에 하늘로 열린 마당","more":"빌라 사보아: 바닥부터 천장까지 유리 벽이 내부의 중정을 면함. 라 투레트 수도원 평면에도 내부 중정."},{"ko":"썬큰","en":"sunken","say":"바닥보다 낮게 파 넣은 것. 빌라 사보아의 썬큰 욕조","more":"빌라 사보아 마스터 베드룸: 회색 타일의 파란색 줄눈으로 된 썬큰 욕조."},{"ko":"셰이즈","en":"chasie","say":"드러누울 수 있는 의자","more":"빌라 사보아 마스터 베드룸의 빌트인된 단으로 만든 셰이즈. 슬라이드 철자 chasie는 chaise의 오타로 보여요."},{"ko":"유니테 다비타시옹","en":"Unite d'Habitation","say":"르 코르뷔지에의 대규모 노동자 공동주택","more":"마르세이유 교외, 1952년 완공(캡션 1953, 1947-53). 길이 140m, 높이 24m. 베를린 유니테는 1958."},{"ko":"뷰-포르 구역","en":"","say":"2차 세계대전으로 파괴된 마르세이유의 구역","more":"여기 살던 조선소 노동자들을 이주시키려고 유니테 다비타시옹을 계획."},{"ko":"중복도","en":"","say":"건물 가운데를 지나는 복도","more":"유니테 다비타시옹 채광(Soleil): 중복도와 복층주택 구성으로 모든 주거단위에 적극적 채광."},{"ko":"채광","en":"Soleil","say":"햇빛을 집 안으로 들이는 것. 유니테 기본접근 1","more":"중복도와 복층주택 구성. 모든 주거단위가 아침과 저녁 햇빛을 받도록 남북으로 길게 배치."},{"ko":"","en":"Espace","say":"공간. 유니테 기본접근 2","more":"시트로앵의 설계원리를 근거로 중층의 거실 도입."},{"ko":"녹지","en":"Verdure","say":"푸른 땅. 유니테 기본접근 3","more":"'녹지 위의 고층주거' 개념, 거대한 필로티."},{"ko":"녹지 위의 고층주거","en":"","say":"건물을 높이 세우고 땅은 녹지로 비워 두는 생각","more":"유니테 다비타시옹 녹지(Verdure)의 개념. 거대한 필로티와 함께."},{"ko":"인 시트","en":"in situ","say":"현장에서 콘크리트를 부어 만든 기둥과 보 구조","more":"유니테 다비타시옹: 철근 콘크리트 기둥과 보로 이루어진 '인 시트(in situ) 구조'."},{"ko":"미리 만들어진 부재사용","en":"prefabrication","say":"공장에서 미리 만든 부품을 가져와 올리는 방식","more":"유니테의 반복적인 외피들은 콘크리트로 미리 성형되어 각 위치에 올려짐. 모듈러 원리로 부재의 표준화, 규격화."},{"ko":"노트르담 뒤 오 교회","en":"Colline Notre Dame du Haut","say":"롱샹교회. 1951년 프랑스 롱샹의 곡면 콘크리트 교회","more":"2차 세계대전 이후 작품, 후기 디자인 기법의 극적인 예. 비행기 날개 같은 지붕을 핀(pin)으로 벽 위에 올려 떠 보이게 함. '깊은 몰아와 명상의 배'."},{"ko":"롱샹교회","en":"","say":"노트르담 뒤 오 교회의 다른 이름","more":"라 투레트 수도원 슬라이드에서는 '롱샹성당'. 직교하지 않는 자유로운 공간."},{"ko":"깊은 몰아와 명상의 배","en":"","say":"롱샹교회를 표현한 말","more":"롱샹교회 사진 위에 적힌 문구."},{"ko":"세 개의 탑","en":"","say":"롱샹교회의 탑 세 개. 육중함, 안정감, 안전, 방호의 의미","more":"두 유형의 벽체로 에워쌈과 움직임 표현."},{"ko":"의식용 출입문","en":"pivot","say":"롱샹교회의 에나멜 처리된 회전식 출입문","more":"컬러풀한 창문들, 좌석의 배치, 챈슬의 가구와 함께 모두 건축가가 디자인."},{"ko":"챈슬","en":"","say":"교회 제단 쪽 구역","more":"롱샹교회: 챈슬의 가구들까지 건축가가 디자인해 고딕 교회 인테리어를 연상시키는 신비로운 공간."},{"ko":"칼 마르크스 호프","en":"Karl Marx Hof","say":"길이 1km 블록에 1300세대를 담은 빈의 주거단지(1930)","more":"5-7층, 운동장, 탁아소, 세탁장, 병원, 도서관, 상점. 벽돌 2,500만 개, '작은 붉은 벽돌이 새로운 세계를 건설하다'. 표현주의적 색채와 강한 조형성."},{"ko":"르 코르뷔지에 센터","en":"Centre Le Corbusier","say":"1957년 스위스 취리히 공원의 전시용 파빌리온","more":"입체파적인 모듈러를 기하학적 시스템으로 배열, 유리와 밝은 원색 월 판넬, 길고 돌출된 램프, 가는 기둥이 받치는 강철 거대 지붕. 제목에는 '르 꼬르뷔지에 센터'."},{"ko":"입체파","en":"","say":"사물을 여러 면과 기하학 조각으로 나눠 그리는 미술 흐름","more":"르 코르뷔지에 센터: 입체파적인 모듈러를 기하학적 시스템으로 배열."},{"ko":"월 판넬","en":"","say":"벽을 이루는 판","more":"르 코르뷔지에 센터는 유리와 밝은 원색들로 이루어진 월 판넬 사용."},{"ko":"램프","en":"","say":"층과 층을 잇는 비탈길(경사로)","more":"르 코르뷔지에 센터: 상부층으로 이동하는 길고 돌출된 램프."},{"ko":"기계 시대","en":"machine age","say":"기계와 과학 기술이 이끄는 근대의 세계","more":"르 코르뷔지에 센터: 미학적인 가치 + 근대의 과학 기술에서 비롯된 machine age 세계의 현실들 사이를 연결한 성공작."},{"ko":"라 투레트 수도원","en":"","say":"1960년 프랑스 이브의 노출 콘크리트 수도원","more":"거친 노출 콘크리트 마감, 리듬 있는 개구부, 질서와 혼돈 사이의 강한 긴장감. 빌라 사보아, 유니테, 자유로운 평면, 롱샹을 한데 모음."},{"ko":"노출 콘크리트","en":"","say":"마감재를 덧대지 않고 콘크리트 면을 그대로 드러낸 것","more":"라 투레트 수도원: 거친 노출 콘크리트 마감. 르 코르뷔지에는 거친 마감 콘크리트 사용을 연구한 최초의 건축가."},{"ko":"질서와 혼돈","en":"","say":"라 투레트 수도원에 흐르는 두 힘의 강한 긴장감","more":"복잡하고 풍부한 형태와 함께 나와요."},{"ko":"국제주의 건축","en":"internationale Architektur","say":"그로피우스가 1925년 바우하우스 총서 1권 표제로 쓴 용어","more":"기능과 기술을 따르면 나라가 달라도 건물이 닮는다는 흐름."},{"ko":"중정","en":"Courtyard","say":"건물이 빙 둘러싼 가운데의 큰 마당"}],"8":[{"ko":"미스 반 데어 로에","en":"Ludwig Mies van der Rohe","say":"'적을수록 많다'를 남긴, 그로피우스와 함께 독일의 대표적 기능주의 건축가","more":"1886-1969. 슬라이드 이름 표기는 루드비히 미스 반 데어 로에. 작품 순서: 프리드리히가 마천루와 콘크리트 오피스빌딩 계획안 1922, 브릭 빌라 계획안 1923, 바이센호프 4층 아파트와 랑에 주택 1927, 에스터 주택 1928, 바르셀로나 박람회 독일관 1929, 투겐다트 주택 1930, 판스워스 하우스 1950, 레이크쇼어 드라이브 아파트 1951, 크라운 홀 1955, 신 국립미술관 1968."},{"ko":"기능주의","en":"Functionalism","say":"건물의 사용과 기능을 형태가 그대로 드러내는 건축","more":"8단원 첫 줄: 미스는 발터 그로피우스(Walter Gropius)와 함께 독일의 대표적 기능주의 건축가."},{"ko":"발터 그로피우스","en":"Walter Gropius","say":"미스와 함께 독일의 대표적 기능주의 건축가로 꼽히는 사람","more":"4단원 바우하우스를 세운 사람. 8단원에서는 미스의 짝으로 첫 슬라이드에 나옴."},{"ko":"바이센호프 주거단지","en":"Weissenhof Siedlung","say":"1927년 슈투트가르트의 주택전시회 단지, 미스는 여기서 4층 아파트를 지음","more":"미스의 건물: 지붕테라스를 둔 단순하고 비례적인 4층 건물로 이루어진 아파트. 5단원과 이어짐."},{"ko":"지붕테라스","en":"","say":"지붕 위를 평평하게 만들어 마당처럼 쓰는 공간","more":"바이센호프 주거단지의 미스 아파트(4층 건물)에 있음."},{"ko":"적을수록 많다","en":"Less is more","say":"덜어낼수록 오히려 더 풍부해진다는 미스 반 데어 로에의 말","more":"해석 세 가지: '장식이 적을수록 의미는 풍부해진다', '형식을 절제할수록 본질에 가까워진다', '과거의 양식과 결별할수록 새로운 시대를 더 잘 맞이할 수 있다'."},{"ko":"미학적 순수미","en":"","say":"모더니즘의 정수를 보여 주려고 미스가 더욱 집중한 깨끗하고 순수한 아름다움"},{"ko":"모더니즘","en":"","say":"새 과학기술과 생활방식에 맞춰 모든 예술에 나타난 새 형태의 이름","more":"미스는 모더니즘의 정수를 보여줄 수 있는 미학적 순수미에 더욱 집중."},{"ko":"아방가르드적 이상","en":"","say":"근대화, 산업화 과정에서 새 시대에 맞는 새 미학을 꿈꾼 앞서가는 생각","more":"'적을수록 많다'에 반영된 생각."},{"ko":"브릭 빌라","en":"brick villa","say":"미스의 공간과 건축에 대한 이상을 읽을 수 있는 1923년 주택 계획안","more":"다양한 길이와 두께의 직선들이 외곽으로 무한히 연장되고 내부로는 깊숙이 파고들어 경관을 끌어들임. 1, 2층 층고의 평지붕 매스, 일정한 축(axis) 없이 자유 배치."},{"ko":"계획안","en":"","say":"아직 지은 건물이 아니라 도면과 그림으로 낸 설계 제안","more":"8단원 계획안 셋: 프리드리히가 마천루 계획안(1922), 콘크리트 오피스빌딩 계획안(1922), 브릭 빌라 계획안(1923)."},{"ko":"벽체","en":"","say":"건물의 벽. 미스는 벽을 방을 가두는 상자가 아니라 홀로 선 판처럼 다룸","more":"브릭 빌라: 벽체는 독립해서 서 있는 건축요소로 변형. 벽체들이 서로 어긋나며 내부의 열린 개구부를 형성."},{"ko":"개구부","en":"","say":"벽에 뚫리거나 벽과 벽 사이에 생긴 열린 부분","more":"브릭 빌라: 벽체들이 어긋나면서 내부의 열린 개구부가 생김."},{"ko":"공간의 중첩","en":"","say":"엇갈린 벽 사이로 방과 방이 겹치듯 이어지는 것","more":"브릭 빌라: 벽체가 어긋나 열린 개구부를 만들고, 이로써 내부의 공간들이 중첩."},{"ko":"일정한 축","en":"axis","say":"건물을 대칭으로 줄 세우는 기준선. 미스는 이것 없이 자유롭게 배치","more":"브릭 빌라: 일정한 축(axis) 없이 자유롭게 배치. 바르셀로나 독일관도 대칭이나 축을 강조하는 엄격함과 거리를 둠."},{"ko":"평지붕","en":"Flat Roof","say":"평평한 지붕","more":"브릭 빌라(1, 2층 층고의 평지붕 매스), 투겐다트 주택(비대칭적인 단층의 평지붕 건물)."},{"ko":"매스","en":"Mass","say":"건물이 이루는 큰 덩어리","more":"브릭 빌라는 평지붕의 매스, 판스워스 하우스는 대지로부터 띄워 올려진 매스."},{"ko":"랑에 주택","en":"Haus Lange","say":"독일 크레펠트에 있는 미스의 벽돌 주택(1927)","more":"에스터 주택(1928)과 나란히 소개. 랑에가 1년 먼저."},{"ko":"에스터 주택","en":"Haus Ester","say":"독일 크레펠트에 있는 미스의 벽돌 주택(1928)","more":"랑에 주택(1927)과 짝. 사진에 보이는 것: 붉은 벽돌 벽, 가로로 긴 창, 얇게 내민 평평한 차양."},{"ko":"바르셀로나 박람회 독일관","en":"Barcelona Pavilion","say":"1929년 스페인 바르셀로나 박람회에 미스가 지은 독일 전시관","more":"세 특징: 초록색 대리석으로 표면을 씌운 벽, 회색의 염색된 유리 스크린, 벽과 수평 슬래브의 분리. 여덟 개의 스틸 기둥. 1986년 복원."},{"ko":"바이마르 공화국","en":"Weimar","say":"바르셀로나 독일관이 그 이념을 국제적으로 홍보하려 한 당시 독일 공화국","more":"이상 네 가지: 개방성, 자유, 근대성, 국제주의(openness, liberality, modernity, internationalism)."},{"ko":"개방성, 자유, 근대성, 국제주의","en":"openness, liberality, modernity, internationalism","say":"바르셀로나 독일관이 상징한 바이마르 공화국의 이상 네 가지"},{"ko":"명료성, 단순성, 솔직성","en":"clarity, simplicity, honesty","say":"바르셀로나 독일관 디자인의 원칙 세 가지","more":"구체적인 모습: 초록색 대리석으로 표면을 씌운 벽, 회색의 염색된 유리 스크린, 벽과 수평 슬래브의 분리."},{"ko":"초록색 대리석","en":"","say":"바르셀로나 독일관에서 벽의 표면을 씌운 돌"},{"ko":"염색된 유리 스크린","en":"","say":"바르셀로나 독일관의 회색으로 물들인 유리 칸막이"},{"ko":"벽과 수평 슬래브의 분리","en":"","say":"벽이 지붕판을 받치지 않고 따로 떨어져 서 있는 것","more":"바르셀로나 독일관의 세 특징 중 하나. 지붕은 여덟 개의 스틸 기둥이 지지."},{"ko":"슬래브","en":"","say":"지붕이나 바닥을 이루는 넓고 평평한 판","more":"슬라이드 표기가 섞여 있음: 2쪽, 8쪽 '슬래브', 10쪽 '슬라브'."},{"ko":"수공간","en":"","say":"물을 담아 둔 연못 같은 공간","more":"슬라이드 표기 수(水)공간. 바르셀로나 독일관에서 크롬, 대리석, 유리와 조화를 이루는 시각적 즐거움."},{"ko":"칸막이 같은 벽","en":"","say":"막힌 벽 대신 유리와 대리석 판을 칸막이처럼 세운 벽","more":"바르셀로나 독일관: 불규칙한 배열이지만 직선의 추상적인 패턴으로 배열."},{"ko":"트레버틴","en":"travertine","say":"바르셀로나 독일관의 벽체에 쓰인 돌 재료","more":"두 개의 양단 트레버틴 벽체가 공간을 에워싸며 내부공간을 수용."},{"ko":"스틸 기둥","en":"","say":"강철로 만든 가는 기둥","more":"바르셀로나 독일관: 평평한 슬라브 지붕을 여덟 개의 스틸 기둥이 지지."},{"ko":"십자형 기둥","en":"","say":"단면이 더하기(+) 모양인 크롬 도금 기둥","more":"바르셀로나 독일관: 재료를 최소한으로 사용하면서 혁신적 재료가 줄 수 있는 구조미를 표현."},{"ko":"크롬 도금","en":"","say":"금속 표면에 크롬을 입혀 거울처럼 반짝이게 한 마감","more":"바르셀로나 독일관의 십자형 기둥과 가구 프레임, 투겐다트 주택의 크롬 도금한 철재."},{"ko":"선택적인 요소","en":"","say":"기둥이 지붕을 받치니 벽은 있어도 되고 없어도 되는 요소가 된 것","more":"바르셀로나 독일관: 강철과 콘크리트의 근대적 구조 기술의 능력을 완전히 이용하여 벽들을 선택적인 요소로 만든 건물."},{"ko":"구조미","en":"","say":"꾸밈 대신 구조 자체에서 나오는 아름다움","more":"미스: '구조는 건물의 용도보다 더 중요하며, 용도는 변화할 수 있지만 구조는 그대로 남는다.'"},{"ko":"차가움 속의 시각적 조화","en":"","say":"바르셀로나 독일관의 차갑지만 보기 좋은 조화를 요약한 말","more":"대칭적이거나 축을 강조하는 형식상의 엄격함과 거리를 두고 자유로운 시각적 즐거움을 추구하는 조형 원칙."},{"ko":"비례감","en":"","say":"부분과 부분의 크기 관계가 잘 맞는 느낌","more":"바르셀로나 독일관: 비례감과 기하학적 구성에 비중을 두어 건물 요소들을 총체적인 미적 대상으로 완성."},{"ko":"캔틸레버","en":"cantilever","say":"한쪽 끝만 고정하고 다른 끝은 받침 없이 내민 구조","more":"바르셀로나 독일관: 캔틸레버의 날렵한 지붕."},{"ko":"유동적 공간","en":"","say":"벽에 갇히지 않고 흐르듯 이어지는 공간","more":"가벼운 기둥들이 떠받치는 열린 공간, 캔틸레버의 날렵한 지붕과 함께 '공간의 자유'를 의미."},{"ko":"공간의 자유","en":"","say":"구조와 재료에 구속되지 않는 자유로운 공간","more":"바르셀로나 독일관의 열린 공간, 캔틸레버 지붕, 유동적 공간이 뜻하는 것."},{"ko":"투명성","en":"","say":"유리와 반사로 안과 밖이 비쳐 보이는 성질","more":"바르셀로나: 채색된 유리, 거울과 같이 빛나는 대리석, 크롬 도금의 가구 프레임으로 다양하게 표현. 판스워스: 빛에 의한 투명성과 모호성."},{"ko":"게오르그 콜베","en":"","say":"바르셀로나 독일관에 선 조각상의 작가","more":"슬라이드 캡션 '게오르그 콜베의 조각상'. 독일관의 '몇 개의 모던한 조각 작품들' 중 하나."},{"ko":"투겐다트 주택","en":"Tugendhat Villa","say":"체코 브르노에 있는 미스의 주택(1930)","more":"마노, 대리석, 옅은 유리색, 크롬 도금한 철재 등 풍부한 재료. 작고 비대칭적인 단층의 평지붕 건물. 전, 후면의 개방성과 폐쇄성의 대비가 극명."},{"ko":"마노","en":"","say":"투겐다트 주택에 쓰인 값진 돌 재료","more":"투겐다트 주택 재료 넷: 마노, 대리석, 옅은 유리색, 크롬 도금한 철재."},{"ko":"오닉스","en":"onyx","say":"투겐다트 주택에서 거실과 서재를 나누는 대리석 스크린의 재료","more":"값비싼 재료가 주는 우아함. 소재의 패턴과 질감이 장식을 대신."},{"ko":"마카사르 에보니","en":"Macassar ebony","say":"투겐다트 주택에서 다이닝 공간의 경계를 만드는 곡선 스크린의 재료"},{"ko":"펜트하우스","en":"","say":"맨 위층에 얹힌 집. 투겐다트 주택은 침실들을 최상층에 이렇게 배치"},{"ko":"개방형 거실","en":"","say":"벽으로 막지 않고 넓게 트인 거실","more":"투겐다트 주택: 거실과 서재 부분은 오닉스 대리석 스크린으로만 구획."},{"ko":"개방성과 폐쇄성의 대비","en":"","say":"투겐다트 주택의 앞뒤 한쪽은 열리고 다른 쪽은 닫혀 있는 것","more":"슬라이드: 전, 후면의 개방성과 폐쇄성의 대비가 극명."},{"ko":"아돌프 로스","en":"Adolf Loos","say":"장식을 타락이라 비난하고 라움플란을 쓴 빈 건축가","more":"1870-1933. 제체시온의 심미적 경향을 비판. 작품 순서 카페 무제움, 아메리칸 바(1908), 슈타이너(1910), 로스하우스(1912), 슈트라서(1918), 뮐러(1930)."},{"ko":"장식과 죄악","en":"Ornament und Verbrechen","say":"장식은 쓸모없는 타락의 표현이라 한 로스의 1908년 논문","more":"장식이 기계화된 생산방법에 맞지 않는다는 견해가 20세기 디자인의 중심이 됨."},{"ko":"공간의 영속성","en":"","say":"천장과 바닥을 밋밋하게 남겨 공간이 오래 변하지 않게 하려는 개념","more":"투겐다트 주택: 천장과 바닥 역시 건축적 요소를 가능한 배제."},{"ko":"절대적 필요성","en":"absolutely necessary","say":"꼭 필요한 것만 둔다는 투겐다트 주택 가구 배치의 원칙","more":"오닉스 같은 값비싼 재료의 우아함과 조화되어 궁극적 미와 화려함을 제공."},{"ko":"전후 모더니즘","en":"","say":"전쟁 뒤의 모더니즘. 8단원 후반부(판스워스 하우스부터)의 묶음 제목"},{"ko":"판스워스 하우스","en":"Farnsworth house","say":"네 면이 모두 유리로 된 미스의 주말 전원주택(1950)","more":"Plano, IL, USA. 대지로부터 띄워 올려진 매스를 철골 구조로 지탱, 오픈 리빙 스페이스, 정제된 디자인의 극단적인 예."},{"ko":"철골 구조","en":"","say":"강철 뼈대로 건물을 받치는 구조","more":"판스워스 하우스: 대지로부터 띄워 올려진 매스를 철골 구조로 지탱."},{"ko":"오픈 리빙 스페이스","en":"","say":"벽 없이 하나로 트인 생활 공간","more":"판스워스 하우스(네 면이 모두 유리로 된 주말 전원주택)에 적용."},{"ko":"하나의 섬","en":"island","say":"판스워스 하우스 안에 벽난로, 욕실들, 다용도 공간을 몰아넣은 벽 덩어리","more":"왼쪽 벽 요소들이 하나의 섬(island)을 이루고, 반대편에는 부엌 배치."},{"ko":"정제된 디자인","en":"","say":"필요한 최소한만 남기고 불필요한 요소는 모두 지운 디자인","more":"판스워스 하우스는 정제된 디자인의 극단적인 예."},{"ko":"비움","en":"","say":"내부공간을 비워 미니멀한 효과를 극대화하는 수단","more":"판스워스 하우스: 최소한의 차단이 필요한 공간 외에는 내부 벽체 제거. 설비가 필요한 부엌, 화장실 외의 기능은 매우 유동적."},{"ko":"단순 기하 형태","en":"","say":"네모, 직선처럼 단순한 도형 모양","more":"판스워스 하우스: 단순 기하 형태를 추구하며 물리적인 물성만 드러나는 콘크리트나 유리 사용."},{"ko":"물성","en":"","say":"재료가 가진 그대로의 성질과 느낌"},{"ko":"모호성","en":"","say":"빛에 비쳐 안과 밖의 경계가 흐릿해지는 성질","more":"판스워스 하우스: 빛에 의한 투명성과 모호성으로 건물의 존재감 자체를 극대화."},{"ko":"크라운 홀","en":"","say":"미스가 시카고 IIT에 지은 철과 유리의 건물(1955)","more":"슬라이드에는 설명 글 없이 캡션, 사진 두 장, 도면 두 장."},{"ko":"콘크리트 오피스빌딩 계획안","en":"","say":"미스의 1922년 사무소 건물 계획안","more":"프리드리히가 마천루 계획안과 같은 해(1922). 슬라이드에서 크라운 홀(1955) 다음 쪽에 나옴."},{"ko":"프리드리히가 마천루 계획안","en":"","say":"미스의 1922년 독일 베를린 고층건물 계획안","more":"콘크리트 오피스빌딩 계획안과 같은 해(1922). 사진은 유리로 감싼 듯한 곡면 고층 모형."},{"ko":"마천루","en":"","say":"하늘에 닿을 듯 아주 높은 건물"},{"ko":"레이크쇼어 드라이브 아파트","en":"Lake shore drive","say":"미스가 미국 시카고에 지은 철과 유리의 초고층아파트(1951)","more":"도시의 상점, 레스토랑, 위락시설 등을 편리하게 이용. 그림 속 책 캡션은 1950-1951년."},{"ko":"베를린 신 국립미술관","en":"new national gallery","say":"미스의 1968년 베를린 미술관. 큰 강철 지붕 아래 유리 홀","more":"테라스 베이스, 바깥쪽 모서리의 8개 기둥이 강철 지붕 지지, 지붕선보다 후퇴된 전면 유리벽. 10년간 복원공사 후 2021년 재개관."},{"ko":"테라스 베이스","en":"","say":"폭이 넓고 바닥을 높인 받침. 신 국립미술관의 갤러리, 사무실들, 레스토랑을 둘러쌈"},{"ko":"이성의 오아시스","en":"","say":"대도시의 혼란한 상태 속에 신 국립미술관을 이성의 쉼터로 넣고자 한 생각","more":"함께 나온 말: '예술의 과제는 현시대의 절망적인 혼란 속에 질서를 세우는 것'."},{"ko":"천정도","en":"","say":"천장을 그린 도면. 신 국립미술관 쪽에 나오며 격자 무늬가 보임","more":"슬라이드 표기 그대로 '천정도'. 신 국립미술관 도면은 진입층, 지하층, 천정도."},{"ko":"미스 반 데어 로에","en":"Mies van der Rohe","say":"바우하우스 3대 학장이자 바이센호프 주거단지를 이끈 건축가","more":"1886-1969. 1930년 교장. 바이센호프 1-4번 4층 아파트."}],"9":[{"ko":"프랭크 로이드 라이트","en":"Frank Lloyd Wright","say":"자연과 사람의 관계를 집으로 표현한 미국 건축가","more":"1867-1959. 위스콘신 출생, 개척자의 성향. 아들러와 설리번의 사무실에서 건축 수업. 프레이리형 주택, 낙수장, 구겐하임 미술관."},{"ko":"알바 알토","en":"Alvar Aalto","say":"나무와 곡선으로 따뜻한 모더니즘을 만든 핀란드 건축가, 가구디자이너","more":"1898-1976. 전후 모더니즘 건축가. \"형태의 창조자\". 파이미오 안락의자."},{"ko":"단크마어 아들러","en":"","say":"라이트가 건축을 배운 사무실의 건축가","more":"1844-1910. 루이스 설리번과 같은 사무실(2단원 '아들러 앤드 설리번')."},{"ko":"루이스 설리번","en":"Louis Sullivan","say":"\"형태는 기능을 따른다\"고 말한 시카고 학파 건축가, 라이트의 스승","more":"2단원 표기 1856-1924. 9강 슬라이드에는 1986-1924로 잘못 적혀 있음."},{"ko":"형태는 기능을 따른다","en":"form follows functions","say":"건물 모양은 쓰임새에서 나와야 한다는 설리번의 말","more":"형태의 미는 필연적으로 기능을 표현하는 데서 나온다는 의미. 표현을 정직하게 하는 것이 아름다운 건물의 필수 선결조건. 라이트가 아니라 설리번의 말."},{"ko":"프레이리형 주택","en":"","say":"미국 대초원처럼 낮고 길게 깔린 라이트의 초기 주택","more":"대초원 주택이라고도 함. 시카고 근교 오크파크와 리버사이드. 순서: 윈슬로(1894), 윌리츠(1903), 로비(1908)."},{"ko":"오크파크","en":"","say":"프레이리형 주택들이 세워진 시카고 근교 지역","more":"리버사이드와 짝으로 나옴."},{"ko":"리버사이드","en":"","say":"오크파크와 함께 프레이리형 주택이 세워진 시카고 근교 지역"},{"ko":"윈슬로 하우스","en":"","say":"프레이리형 주택 목록의 맨 처음 작품","more":"1894. 윈슬로(1894), 윌리츠(1903), 로비(1908) 순서."},{"ko":"윌리츠 하우스","en":"House Willits","say":"십자형 평면이 밖으로 뻗은 라이트의 프레이리형 주택","more":"1903, 미국 일리노이. 회반죽 흰 벽 + 짙은 나무 프레임, 빌트인 좌석으로 둘러싸인 개방형 벽난로가 평면의 핵심. \"상자 형태를 파괴했다\"."},{"ko":"로비 하우스","en":"Robie House","say":"낮은 지붕과 창문 띠가 길게 이어진 시카고의 프레이리형 주택","more":"1908, 미국 시카고. 연속적인 창문 띠로 벽체 형성, 벽체는 지붕과 분리, '입체파' 성격의 외부 형태, 지면에 견고하게 부착."},{"ko":"타탄 체크의 그리드 플랜","en":"","say":"체크무늬 같은 격자를 깔고 방을 배치하는 평면","more":"프레이리형 주택의 속성과 특징 목록의 첫 설계 항목."},{"ko":"수평 띠","en":"","say":"창문을 정리해 가로로 길게 이은 띠","more":"프레이리형 주택: '창문을 정리하여 수평 띠를 만드는 것'. 로비 하우스: 연속적인 창문 띠로 벽체 형성."},{"ko":"완만한 경사지붕","en":"","say":"기울기가 낮고 처마가 길게 나온 지붕","more":"프레이리형 주택: '완만한 경사지붕의 처마 강조'. 라이트 주택의 특징: '수평적인 경사지붕'."},{"ko":"부가적인 벽","en":"","say":"건물 본체에 덧붙여 쓰는 벽","more":"프레이리형 주택의 속성과 특징 목록 항목."},{"ko":"십자형 평면","en":"","say":"열십자 모양으로 방들이 사방으로 뻗은 평면","more":"윌리츠 하우스: 십자형 평면이 외부로 확장. 유니티 교회도 실내 십자의 중앙에 천창."},{"ko":"개방형 벽난로","en":"","say":"벽으로 가두지 않고 트인 곳에 둔 벽난로, 라이트 집의 중심","more":"윌리츠: 빌트인 좌석으로 둘러싸여 평면의 핵심. 라이트 주택: 수평요소와 수직요소를 결합하는 주택 전체의 절정이자 중심(가정의 난로가 주는 실존적 의미)."},{"ko":"빌트인 좌석","en":"","say":"벽이나 바닥에 붙박이로 만든 의자","more":"윌리츠의 개방형 벽난로를 둘러쌈. 낙수장의 붙박이 벤치도 라이트 자신의 디자인."},{"ko":"상자 형태의 파괴","en":"","say":"네모난 상자 같은 집을 깨고 공간을 밖으로 펼친 것","more":"윌리츠 하우스 슬라이드의 문구 \"상자 형태를 파괴했다\". 공간의 연속성과 함께 기억."},{"ko":"공간의 연속성","en":"","say":"방과 방이 끊기지 않고 이어지는 느낌","more":"윌리츠 하우스의 특징 목록 항목."},{"ko":"입체파 성격의 외부 형태","en":"","say":"날카로운 각진 면들이 절묘하게 만나는 외관","more":"로비 하우스. 슬라이드는 '입체파'에 따옴표를 붙임."},{"ko":"상호관입","en":"","say":"공간과 공간이 서로 파고들어 겹치는 것","more":"라이트 주택의 특징 '상호관입한 공간'. 낙수장: 내부, 외부의 상호관입 + 내부공간의 상호관입."},{"ko":"내외부 공간의 모호한 구분","en":"","say":"안과 밖의 경계를 흐리게 한 것","more":"라이트 주택의 특징. 주택과 풍경을 이어주는 테라스와 짝."},{"ko":"테라스","en":"","say":"집과 바깥 풍경을 이어 주는 열린 바닥","more":"라이트 주택: 유기적으로 해석된 개방 공간. 낙수장 테라스 바닥은 세 방향의 전망을 제공."},{"ko":"유니티 교회","en":"","say":"건물을 둘로 나누고 입구부로 이은 라이트의 콘크리트 교회","more":"1907, 미국 일리노이. 콘크리트 자체를 외벽 재료로, 종교와 비종교적 기능 분리(기능주의), 신자들의 공간, 실내 장식이 데 스테일에 영향."},{"ko":"두 핵으로 구분된 공간","en":"","say":"유니티 교회를 두 덩어리로 나눈 배치","more":"정신과 물질의 대비, 신과 현세의 대비. 평면에 UNITY TEMPLE과 UNITY HOUSE가 따로 있음."},{"ko":"갤러리층","en":"","say":"큰 실내를 빙 둘러 위쪽에 낸 발코니 같은 층","more":"유니티 교회: 3층 높이의 내부공간은 중2층 및 사각형 평면의 3변을 둘러싼 갤러리층으로 구성."},{"ko":"천창","en":"","say":"천장이나 지붕에 낸 하늘 쪽 창","more":"유니티 교회(실내 십자의 중앙), 존슨 왁스 본부(콘크리트 원 모양들 사이), 구겐하임(천창 돔)."},{"ko":"탤리에신","en":"Taliesin","say":"웨일스어로 '빛나는 언덕'이라는 뜻의 라이트의 집","more":"슬라이드 캡션: 스프링 그린, 위스콘신, 1929. 저층의 단층 건물이 언덕 위에서 자연과 조화, 경사진 천장, 큰 돌을 쌓은 벽난로 공간의 거실."},{"ko":"낙수장","en":"Falling Water, House Kaufmann","say":"폭포 위에 캔틸레버 테라스를 겹쳐 띄운 라이트의 주택","more":"1939, 미국 펜실베니아. 라이트의 유기적 주거건축의 결정체. 땅의 혼(Genius Loci)에 부응, 장소에 대한 관심."},{"ko":"캔틸레버","en":"","say":"한쪽 끝만 붙잡고 허공으로 쭉 내민 수평 구조","more":"낙수장의 수평적 요소. 미국의 광활한 대지와 조화."},{"ko":"땅의 혼","en":"Genius Loci","say":"그 장소만이 가진 고유한 성격","more":"낙수장은 땅의 혼에 부응, 장소에 대한 관심. 디자인에 대지의 퇴적 지질을 반영."},{"ko":"대지의 퇴적 지질","en":"","say":"땅에 켜켜이 쌓인 바위층의 결","more":"낙수장 디자인에 반영. 모든 수직 요소는 석재로 마감."},{"ko":"유기적 건축","en":"Organic Architecture","say":"나무가 자라듯 주변 자연과 한 몸이 되는 건축","more":"국제주의 건축과 대립되는 개념. Gaudi, Wright, Art Nouveau 건축가, Aalto 등. 친근한 재료, 자연의 곡선, Human Scale, 유기생명체 같은 Hierarchy."},{"ko":"인간적 척도","en":"Human Scale","say":"사람 몸 크기에 맞춘 크기 감각","more":"유기적 건축의 특징(Human Scale)이자 알토의 스칸디나비아 디자인(인간적 척도)."},{"ko":"전일적 세계관","en":"","say":"세상을 하나로 이어진 전체로 보는 관점","more":"슬라이드 제목 '전일적 세계관과 유기적 디자인'."},{"ko":"기계론적 세계관","en":"","say":"세상을 부품이 맞물린 기계처럼 보는 관점","more":"이것에 기초한 공간구축의 흐름과 달리 유기론적 세계관을 바탕으로 하는 흐름이 따로 있음."},{"ko":"유기론적 세계관","en":"","say":"세상을 살아 있는 생명체처럼 보는 관점","more":"1890년대부터 1910년대까지 아르누보, 유겐트슈틸 등의 자연주의적 경향으로 나타남. 자연이 모든 구축 형태의 원형."},{"ko":"존슨 왁스 본부","en":"S.C. Johnson Wax Headquarters","say":"접시 머리를 단 콘크리트 기둥이 숲처럼 선 라이트의 사무 건물","more":"1939, 미국 위스콘신 라신. S. C. 존슨 왁스 공장에 세워진 행정 업무용 빌딩. 벽체는 하중을 받지 않음, 모서리 없는 공간, 상부 채광."},{"ko":"great room","en":"","say":"존슨 왁스 본부의 크고 탁 트인 업무 공간","more":"콘크리트 구조 기둥들이 압도적 분위기 형성, 기둥들은 천장의 접시형 요소들로부터 퍼져 나옴. 평면 이름표는 Great Workroom."},{"ko":"접시형 요소","en":"","say":"존슨 왁스 본부 기둥 꼭대기의 둥근 접시 모양","more":"기둥들은 천장에 있는 접시형 요소들로부터 퍼져 나옴. 콘크리트 원 모양들 사이에 천창 배치로 일광 제공."},{"ko":"시카고 학파","en":"","say":"1871년 대화재 뒤 철골과 엘리베이터로 고층 사무소를 지은 흐름","more":"철골에 테라코타 외벽, 베이스, 바디, 코니스의 3부분 분할, 시카고 창."},{"ko":"아르 누보","en":"Art Nouveau","say":"과거 양식 대신 자연의 곡선으로 새 양식을 만든 예술 사조","more":"프랑스어로 새로운 미술. 1890-1910, 최고조 1890-1905. '예술에는 일정한 형식이 없다'. 비대칭, 철과 유리, 공간보다 표면과 장식."},{"ko":"유겐트슈틸","en":"Jugendstil","say":"아르누보를 독일어로 옮긴, 곡선을 기하학적으로 정리한 독일 양식","more":"1896년 같은 이름(young style)의 잡지 발간과 함께 시작. 첫 사례는 베렌스의 1898년 그래픽."},{"ko":"데 스테일","en":"De Stijl","say":"직선과 면, 3원색과 무채색만 쓰는 네덜란드 예술 운동","more":"1917년 로테르담의 잡지에서 시작. 창단선언: 자연과 대립하는 기계미학을 건축의 근본으로."},{"ko":"기능주의","en":"Functionalism","say":"건물의 목적이 되는 사용과 기능을 형태가 그대로 표현하는 건축","more":"좋은 디자인의 미학은 특정 형태가 아니라 테크놀로지의 재현에 있음."},{"ko":"국제주의 건축","en":"internationale Architektur","say":"그로피우스가 1925년 바우하우스 총서 1권 표제로 쓴 용어","more":"기능과 기술을 따르면 나라가 달라도 건물이 닮는다는 흐름."},{"ko":"모서리 없는 공간","en":"","say":"각진 구석 없이 둥글게 흐르는 실내","more":"존슨 왁스 본부: 자연스럽게 흐르는 내부공간. 발코니의 띠도 곡면."},{"ko":"상부 채광","en":"","say":"옆 창 대신 위에서 빛을 들이는 방법","more":"존슨 왁스 본부: 내부 지향의 공간 디자인."},{"ko":"구겐하임 미술관","en":"","say":"나선형 램프가 감겨 올라가는 뉴욕의 둥근 미술관","more":"1959, 뉴욕. 둥근 깔때기 형태의 공간, 작품보다 관람객들을 전시. 1959는 라이트(1867-1959)의 마지막 해와 같음."},{"ko":"로툰다","en":"rotunda","say":"둥근 원형의 큰 중앙 홀","more":"구겐하임: 박물관의 주 로툰다 공간은 거대한 나선형의 램프에 의해 만들어짐."},{"ko":"램프","en":"ramp","say":"계단 대신 완만하게 비탈진 통로","more":"구겐하임: 예술 작품들은 램프의 곡선을 따라서 바깥쪽 벽에 전시."},{"ko":"천창 돔","en":"","say":"구겐하임 꼭대기의 빛이 들어오는 둥근 지붕","more":"방문객들은 아래 바닥 부분을 내려다보거나 위의 천창 돔을 올려다볼 수 있음. 색상은 크림색, 식물이 초록색 액센트."},{"ko":"전후 모더니즘","en":"","say":"전쟁이 끝난 뒤 이어진 모더니즘","more":"슬라이드가 알토를 부르는 말 '전후 모더니즘 건축가'."},{"ko":"스칸디나비아 디자인","en":"","say":"북유럽의 장인정신, 수공예를 현대적 기능주의와 합친 디자인","more":"간결한 디자인, 인간적 척도, 천연목재의 성질을 이용한 아름다운 디자인."},{"ko":"파이미오 안락의자","en":"","say":"휘어진 나무 틀로 만든 알토의 안락의자","more":"알토가 건축가이자 가구디자이너임을 보여 주는 사진."},{"ko":"파이미오 결핵요양소","en":"","say":"알토가 핀란드 파이미오에 지은 결핵 요양 시설","more":"1933, 핀란드 파이미오. '알토의 유기적 건축' 슬라이드의 사진."},{"ko":"특수해","en":"","say":"어디에나 같은 답(보편해) 대신 그 장소만의 답","more":"알토의 유기적 건축: 보편해보다는 특수해를, 법칙과 체계보다는 다양성을 목표로 함."},{"ko":"동적인 건축","en":"","say":"멈춰 있는 듯한 건축이 아니라 움직이는 듯한 건축","more":"알토: '정적인 건축이 아닌 동적인 건축'."},{"ko":"낭만적 자연주의","en":"","say":"자연을 감성적으로 바라보는 태도","more":"알토의 유기적 건축은 낭만적 자연주의로부터 기원."},{"ko":"인본주의","en":"","say":"사람을 가장 중심에 두는 생각","more":"알토: 인간의 육체적 정서적 욕구에 대한 관심. 공식 '합리성 + 인간성 + 자연'."},{"ko":"헬싱키 대학 오디토리움","en":"","say":"붉은 벽돌 외관과 곡면 천장을 가진 알토의 대학 강당","more":"슬라이드 표기 '헬싱키 대학(알토 대학) 오디토리움, 핀란드 헬싱키, 1966'. 자연재료 선호."},{"ko":"형태의 창조자","en":"","say":"알토를 부르는 별명","more":"헬싱키 대학 오디토리움 슬라이드에 나옴. 라이트가 아니라 알토."},{"ko":"반균질공간","en":"","say":"어디나 똑같은 공간을 거부한 알토 주택의 공간","more":"Alvar Aalto 주택의 특징 '반균질공간의 건축'."},{"ko":"부정형","en":"","say":"반듯하게 정해진 모양이 아닌 형태","more":"알토 주택의 전체 윤곽은 부정형. L 또는 ㄷ자형으로 외부공간을 둘러쌈."},{"ko":"시각적 밸런스","en":"","say":"규칙적 반복 대신 눈으로 보아 균형이 맞게 하는 것","more":"알토 주택: 구조나 형태의 규칙적 반복을 지양, 규칙성보다 시각적 밸런스 추구."},{"ko":"메종 카레","en":"","say":"알토가 프랑스 기욘에 지은 주택","more":"1959, 프랑스 기욘. 알토 주택 목록에서는 'Carre 주택(1959)'."},{"ko":"알토 자택 겸 스튜디오","en":"Aalto House & Studio","say":"알토가 살면서 일한 집, 흰 벽과 짙은 나무 판 외관","more":"슬라이드 캡션은 1939. 그러나 알토 주택의 특징 쪽 목록은 'Aalto 주택(1936)'. 연도 두 개 주의."},{"ko":"빌라 마이레아","en":"Mairea","say":"국제주의의 질서에 나무와 자유로운 형태를 더한 알토의 전원주택","more":"1939, 노르마르크, 핀란드. 건축적 콜라주, S자의 유동적 내부공간 연결, 침엽수림의 추상적 표현. 목록 표기는 Mairea 주택(1939)."},{"ko":"건축적 콜라주","en":"","say":"여러 재료와 형태를 오려 붙인 듯 섞은 외관","more":"빌라 마이레아: 형태적으로나 의미적으로 작품을 풍성하게 완성."},{"ko":"S자의 유동적 내부공간","en":"","say":"S자로 흐르듯 이어지는 실내 공간 연결","more":"빌라 마이레아의 특징."},{"ko":"침엽수림의 추상적 표현","en":"","say":"핀란드 숲을 실내 요소로 단순하게 옮긴 표현","more":"빌라 마이레아. 핀란드 대부분에서 볼 수 있는 침엽수림. 전통과 감성: 곡면, 목재, 빛."},{"ko":"한자지구 아파트","en":"Hansa","say":"알토가 독일 베를린에 지은 ㄷ자형 아파트 블록","more":"1957, 독일 베를린. 콘크리트 슬래브 반복 파사드, 모듈화된 유닛, 줄눈의 격자형 패턴, 단일 색채."},{"ko":"클러스터 형식","en":"","say":"단위세대를 송이처럼 한데 모아 묶은 배치","more":"한자지구 아파트: 남측과 북측 양 끝단에 클러스터 형식으로 단위세대 배치. 그래서 양 끝이 부풀고 가운데가 좁은 ㄷ자 매스."},{"ko":"모듈화된 유닛","en":"","say":"같은 크기 단위로 규격화한 부품","more":"한자지구 아파트: 창과 문, 창틀은 디테일에 따라 모듈화된 유닛으로 구성."},{"ko":"단일 색채","en":"","say":"한 가지 색만 쓰는 것","more":"한자지구 아파트: 단순성과 구조적인 아름다움을 더욱 강조."},{"ko":"국제주의 양식","en":"International Style","say":"히치콕과 존슨의 1932년 책으로 굳어진 새 양식의 이름","more":"책 이름은 '국제주의 양식 : 1922년 이후의 건축'. 용어를 먼저 쓴 사람은 그로피우스."},{"ko":"캔틸레버","en":"cantilever","say":"한쪽 끝만 고정하고 다른 끝은 받침 없이 내민 구조"}]};
